INSERT INTO NPC (npcID, name, biography, contribution, asset) VALUES
(4, 'Lee Kuan Yew', 'Perdana Menteri Singapura yang menyokong penggabungan dengan Malaysia.', 'Memimpin referendum Singapura dan menangani ancaman pengaruh komunis.', 'lee_kuan_yew.png'),
(5, 'Tun Abdul Razak bin Dato'' Hussein', 'Timbalan Perdana Menteri Persekutuan Tanah Melayu dan Pengerusi JAK.', 'Merangka hak perlembagaan dan perlindungan khas bagi Sabah dan Sarawak.', 'tun_abdul_razak.png'),
(1, 'Tunku Abdul Rahman Putra Al-Haj', 'Perdana Menteri pertama Persekutuan Tanah Melayu dan Bapa Kemerdekaan.', 'Meyakinkan lima wilayah bersatu tanpa paksaan: mendengar Borneo, menandatangani perjanjian dan mengisytiharkan Malaysia.', 'tunku_abdul_rahman.png'),
(2, 'Tun Temenggong Jugah anak Barieng', 'Pemimpin utama masyarakat Iban dari Sarawak dan pengerusi parti PESAKA.', 'Menegaskan perlindungan hak adat Sarawak dalam rundingan pembentukan Malaysia.', 'tun_temenggung_jugah.png'),
(3, 'Donald Stephens (Tun Fuad Stephens)', 'Tokoh utama Sabah dan Pengerusi Jawatankuasa Setia Kawan Malaysia (JSKM).', 'Membawa suara rakyat Borneo ke meja perundingan supaya hak mereka ditulis dalam Perlembagaan.', 'tun_muhammad_fuad_stephens.png'),
(6, 'Tan Sri Stephen Kalong Ningkan', 'Ketua Menteri Sarawak yang pertama dan pengasas Perikatan Sarawak.', 'Memimpin Sarawak menyertai Malaysia dan membaca Pemasyhuran di Kuching.', 'tan_sri_dato_amar_stephen_kalong.png'),
(7, 'Wakil SUPP / Pembangkang', 'Wakil gerakan politik tempatan di Sarawak yang menentang idea gabungan awal.', 'Menuntut kemerdekaan Sarawak secara berasingan sebelum cadangan persekutuan.', 'orang_sarawak.png'),
(9, 'Tun Datu Mustapha bin Datu Harun', 'Pengasas USNO dan Pemimpin Utama Sabah.', 'Memimpin penyatuan rakyat Sabah dan menyokong pembentukan Malaysia.', 'tun_dato_mustapha.png'),
(10, 'Tun Muhammad Ghazali Shafie', 'Diplomat dan perunding keselamatan negara dalam rundingan pembentukan Malaysia.', 'Menjaga keselamatan dan diplomasi di belakang tabir: menghadapi Konfrontasi dan memastikan PBB mengesahkan pilihan rakyat.', 'tun_muhammad_ghazali_shafie.png')
INSERT INTO Narrative (narrativeID, narrativeTitle, eraID, summary) VALUES
(1, 'Perjalanan Sang Arsitek', 1, 'Masuki peranan Tunku Abdul Rahman dalam merancang dan memimpin pembentukan Malaysia. Hadapi siri perundingan diplomatik, tinjauan rakyat Borneo, tuntutan perlembagaan, bantahan SUPP, ancaman Konfrontasi Indonesia, tuntutan Filipina, serta siasatan PBB sebelum mengisytiharkan kelahiran negara pada 16 September 1963. Naratif ini merangkumi keenam-enam topik utama: cadangan Malaysia, JSKM dan Cobbold, JAK, ancaman keselamatan, Perjanjian London dan PBB, serta Pemasyhuran.'),
(2, 'Suara Kebangkitan Borneo', 1, 'Ikuti perjuangan pembentukan Malaysia dari sudut pandang pemimpin Borneo. Libatkan diri dalam siri penerangan JSKM, perundingan Suruhanjaya Cobbold, penggubalan Hak 20 Perkara Sabah dalam JAK, penentangan tentera Konfrontasi di sempadan, siasatan PBB, hingga hari Pemasyhuran di Kota Kinabalu dan Kuching. Naratif ini merangkumi keenam-enam topik utama: cadangan Malaysia, JSKM dan Cobbold, JAK, ancaman keselamatan, Perjanjian London dan PBB, serta Pemasyhuran.'),
(3, 'Perisai Diplomasi dan Keamanan', 1, 'Sertai peranan Tun Ghazali Shafie dan pasukan diplomatik negara. Menganalisis ancaman komunis, memimpin tinjauan Suruhanjaya Cobbold, merangka Perlembagaan JAK, menangkis bantahan SUPP, menghadapi Konfrontasi Indonesia dan tuntutan Filipina, serta mengendalikan siasatan PBB (UNMM) demi keselamatan Malaysia. Naratif ini merangkumi keenam-enam topik utama: cadangan Malaysia, JSKM dan Cobbold, JAK, ancaman keselamatan, Perjanjian London dan PBB, serta Pemasyhuran.');
INSERT INTO Scene (sceneID, sceneStoryline, sceneOrder, narrativeID, asset) VALUES
('e1_n1_s1', '27 Mei 1961, Hotel Adelphi, Singapura. Kau, Tunku Abdul Rahman, berdiri di hadapan wartawan tempatan dan asing dengan satu cadangan yang akan mengubah peta Asia Tenggara.', 1, 1, 'grand_hotel_ballroom.png'),
('e1_n1_s2', '1961–1962, Kuching dan Kota Kinabalu. Kau menghantar wakil untuk mendengar rakyat Borneo. Kau tidak mahu keputusan sebesar ini dibuat tanpa suara mereka.', 2, 1, 'lawatan_ke_sarawak.png'),
('e1_n1_s3', '30 Ogos 1962, Kuala Lumpur. Jawatankuasa Antara Kerajaan bersidang. Kau perlu memastikan hak Sabah dan Sarawak ditulis dalam Perlembagaan, bukan hanya dijanjikan dengan lisan.', 3, 1, 'bilik_mesyuarat_formal.png'),
('e1_n1_s4', '1962–1963, Kuala Lumpur. Tiga ancaman tiba serentak di mejamu: SUPP, Konfrontasi dan Filipina. Kau mesti menemui buktinya sebelum memutuskan langkah.', 4, 1, 'bilik_strategi_keselamatan.png'),
('e1_n1_s5', '9 Julai hingga 14 September 1963, London. Kau menandatangani Perjanjian Malaysia, tetapi Indonesia dan Filipina belum puas hati. PBB akan bertanya kepada rakyat Borneo sendiri.', 5, 1, 'bilik_mesyuarat_london.png'),
('e1_n1_s6', '16 September 1963, Stadium Merdeka, Kuala Lumpur. Kau berdiri untuk membaca Pemasyhuran Malaysia yang akan diisytiharkan serentak di empat bandar.', 6, 1, 'laungan_di_stadium_merdeka.png'),
('e1_n2_s1', '1961, Jesselton (Kota Kinabalu). Kau, Donald Stephens, berdiri di balai perhimpunan. Tunku sudah membuat pengumuman di Adelphi dan kini rakyat menunggu kau menjawab.', 1, 2, 'petempatan_pedalaman_sabah.png'),
('e1_n2_s2', '1961–1962, rumah panjang di Sarawak dan pejabat daerah di Sabah. Kau mengetuai JSKM supaya rakyat memahami Malaysia, dan Suruhanjaya Cobbold datang mendengar mereka.', 2, 2, 'bilik_jskm.png'),
('e1_n2_s3', '30 Ogos 1962, Kuching dan Kota Kinabalu. Kau dalam sesi perundingan JAK. Hak Sabah dan Sarawak mesti ditulis dalam Perlembagaan, bukan hanya diingat.', 3, 2, 'bangunan_perlembagaan.png'),
('e1_n2_s4', '1962–1963, sempadan Sabah dan Sarawak. Kau berdepan bantahan SUPP, tentera Konfrontasi dan tuntutan Filipina. Kau mesti menemui buktinya untuk menenangkan rakyat.', 4, 2, 'bilik_strategi_keselamatan.png'),
('e1_n2_s5', 'Julai hingga September 1963, Kuching dan Kota Kinabalu. Perjanjian Malaysia sudah ditandatangani, dan pegawai PBB datang bertanya kepada rakyat Borneo sendiri.', 5, 2, 'bilik_UNMM.png'),
('e1_n2_s6', '16 September 1963, Padang Merdeka, Kota Kinabalu dan Kuching. Kau membacakan Pemasyhuran Malaysia di hadapan rakyat Sabah. Pada hari yang sama pemimpin Sarawak melakukannya di Kuching.', 6, 2, 'laungan_di_stadium_merdeka.png'),
('e1_n3_s1', '27 Mei 1961, Kuala Lumpur. Kau, Tun Ghazali Shafie, membaca keadaan keselamatan Asia Tenggara selepas pengumuman Tunku. Komunis tidak menunggu sesiapa.', 1, 3, 'bilik_strategi_keselamatan.png'),
('e1_n3_s2', '1961–1962, Kuala Lumpur. Kau dan Wong Pow Nee dalam Suruhanjaya Cobbold turun mendengar rakyat Borneo. Keraguan mereka akan dibawa ke JAK.', 2, 3, 'bilik_suruhanjaya_cobbold.png'),
('e1_n3_s3', '30 Ogos 1962, Kuala Lumpur. Kau, Tun Ghazali Shafie, membantu Jawatankuasa Antara Kerajaan menulis jaminan hak Sabah dan Sarawak ke dalam Perlembagaan.', 3, 3, 'bangunan_perlembagaan.png'),
('e1_n3_s4', '1962–1963, Kuala Lumpur. SUPP, Konfrontasi dan Filipina menekan serentak. Kau perlu mengenal pasti bukti ancaman keselamatan sebelum menasihati Tunku.', 4, 3, 'perancangan_pembentukan_malaysia.png'),
('e1_n3_s5', '9 Julai hingga 14 September 1963, London dan Borneo. Perjanjian Malaysia sudah ditandatangani. Kau menasihati Tunku bagaimana melayan misi siasatan PBB.', 5, 3, 'bilik_UNMM.png'),
('e1_n3_s6', '16 September 1963, Kuala Lumpur. Kau memastikan Pemasyhuran Malaysia berjalan serentak di empat bandar, tanpa gangguan keselamatan.', 6, 3, 'laungan_di_stadium_merdeka.png');
INSERT INTO Quest (questID, sceneID, questName, instruction, questType, description, questContent) VALUES
(1, 'e1_n1_s1', 'Hujah Gagasan Tunku', 'Bantu Tunku Abdul Rahman menyampaikan empat faktor utama pembentukan Malaysia kepada media antarabangsa.', '3', 'Memahami faktor pembentukan Malaysia iaitu membendung komunis, keseimbangan kaum, mempercepat kemerdekaan, dan memajukan sosioekonomi.', '{"prompt": "Wartawan bertanya kepada kau: apakah empat faktor utama yang menjadi asas cadangan pembentukan Malaysia?", "options": [{"text": "Membendung komunis, mengimbangi kaum, mempercepat kemerdekaan Borneo dan memajukan ekonomi.", "isCorrect": true}, {"text": "Membendung komunis, mengimbangi kaum, mengekalkan British di Borneo dan memajukan ekonomi.", "isCorrect": false, "consequence": "Akhbar menulis bahawa Tunku mahu British kekal di Borneo. Pemimpin Sabah dan Sarawak berhenti mempercayai cadangan itu sebelum perundingan bermula."}, {"text": "Membendung komunis, menyeragamkan kaum, mempercepat kemerdekaan Borneo dan menambah wilayah.", "isCorrect": false, "consequence": "Wartawan menulis bahawa Tanah Melayu mahu menakluk Borneo. Pemimpin tempatan menolak untuk duduk berunding."}], "aftermath": "Cadangan kau diterima dengan syak wasangka. Sebelum perundingan bermula, kepercayaan sudah mula hilang.", "turns": [{"after": 3, "options": [{"text": "Membendung komunis, mengimbangi kaum, mempercepat kemerdekaan dan memajukan ekonomi.", "isCorrect": true, "reaction": "Tepat, Tunku. Ringkas dan jelas. Tiada siapa boleh kata kita menyorok sesuatu."}, {"text": "Membendung komunis, mengimbangi kaum, menambah cukai dan menguatkan tentera.", "isCorrect": false, "reaction": "Tunku, cukai dan tentera bukan sebab kita. Akhbar akan menulis bahawa gagasan ini membebankan rakyat."}, {"text": "Menyeragamkan bahasa, menyeragamkan agama, mempercepat kemerdekaan dan memajukan ekonomi.", "isCorrect": false, "reaction": "Kita tidak mahu menyeragamkan sesiapa, Tunku. Itu yang paling ditakuti wilayah Borneo."}], "clue": "Ghazali menyebut empat sebab, dan salah satunya tentang kemerdekaan wilayah Borneo."}]}'),
(2, 'e1_n1_s2', 'Analisis Laporan Suruhanjaya Cobbold', 'Nyahkod laporan rasmi Suruhanjaya Cobbold yang diserahkan pada 21 Jun 1962 untuk menentukan pendirian rakyat Sabah dan Sarawak.', '5', 'Mengenal pasti dapatan Laporan Suruhanjaya Cobbold 1962.', '{"clueText": "Laporan mencatatkan satu pertiga penduduk menyokong penuh tanpa syarat, satu pertiga menyokong dengan syarat hak mereka dipelihara, dan satu pertiga lagi mahukan kemerdekaan berasingan terlebih dahulu.", "options": [{"text": "Dua pertiga penduduk menyokong Malaysia, sebahagiannya dengan syarat hak mereka dipelihara.", "isCorrect": true}, {"text": "Dua pertiga penduduk menyokong Malaysia tanpa sebarang syarat dan tuntutan.", "isCorrect": false, "consequence": "Jika kau mengabaikan syarat rakyat, perundingan JAK bermula tanpa tahu apa yang mereka mahu. Wakil Borneo merasa tidak didengar."}, {"text": "Separuh penduduk menyokong Malaysia dan separuh lagi mahu pungutan suara baharu.", "isCorrect": false, "consequence": "Jika kau menganggap rakyat berpecah dua, perundingan ditangguh tanpa sebab. Konfrontasi dan Filipina mengambil kesempatan."}], "aftermath": "Kau membaca laporan yang anggaran sahaja, tanpa memahami syarat rakyat. Perundingan seterusnya bermula dengan salah faham.", "turns": [{"after": 3, "options": [{"text": "Tidak. Suruhanjaya Cobbold datang untuk mendengar pandangan anda sendiri.", "isCorrect": true, "reaction": "Itu yang mereka perlukan, Tunku. Mereka mahu didengar, bukan diarah."}, {"text": "Ya. Keputusan sudah dibuat, suruhanjaya ini hanya untuk mengesahkannya.", "isCorrect": false, "reaction": "Kalau itu yang kau katakan, mereka berhenti bercakap. Laporan itu tidak bernilai lagi."}, {"text": "Tidak. Pemimpin akan bercakap bagi pihak anda semasa suruhanjaya datang.", "isCorrect": false, "reaction": "Orang yang disenyapkan tidak akan mempercayai suruhanjaya mana pun, Tunku."}], "clue": "Ghazali menyebut laporan tidak bernilai jika rakyat rasa dipaksa. Mereka mesti didengar."}]}'),
(3, 'e1_n1_s3', 'Padanan Syarat Perlembagaan JAK', 'Padankan tokoh dan perkara keistimewaan yang diperjuangkan dalam mesyuarat JAK.', '4', 'Memahami fungsi JAK dan peruntukan perlindungan hak Sabah serta Sarawak.', '{"pairs": [{"text": "Lord Lansdowne & Tun Abdul Razak", "pair": 1}, {"text": "Pengerusi bersama Jawatankuasa Antara Kerajaan (JAK)", "pair": 1}, {"text": "Hak 20 Perkara Sabah", "pair": 2}, {"text": "Tuntutan perlindungan khas perlembagaan yang dikemukakan oleh pemimpin Sabah", "pair": 2}, {"text": "Kuasa Imigresen & Agama", "pair": 3}, {"text": "Perkara keistimewaan yang diberikan kepada Sabah dan Sarawak dalam perlembagaan", "pair": 3}, {"text": "Perlakuan Pentadbiran Tempatan", "pair": 4}, {"text": "Perlindungan perkhidmatan awam khas untuk penduduk tempatan Borneo", "pair": 4}], "aftermath": "Hak yang tidak ditulis hilang bersama pemimpin yang berjanji. Wakil Borneo bangun dan meninggalkan dewan.", "turns": [{"after": 3, "options": [{"text": "Menulisnya dalam Perlembagaan Malaysia supaya menjadi undang-undang.", "isCorrect": true, "reaction": "Itu maksud kami, Tunku. Janji boleh dilupa, undang-undang tertulis tidak."}, {"text": "Memasukkannya dalam surat perjanjian sahaja, supaya mudah dipinda kemudian.", "isCorrect": false, "reaction": "Surat perjanjian boleh dipinda diam-diam, Tunku. Kami mahu undang-undang yang tidak mudah diubah."}, {"text": "Menulisnya selepas Malaysia terbentuk, apabila semua pihak sudah tenang.", "isCorrect": false, "reaction": "Selepas itu rakyat kami tiada kuasa berunding, Tunku. Itu bukan jalan yang adil."}], "clue": "Tun Jugah berkata adat mesti ditulis dalam perlembagaan, bukan janji lisan."}]}'),
(4, 'e1_n1_s4', 'Cari Bukti Ancaman Negara', 'Cari bukti fizikal tentangan dalaman dan luaran yang cuba menghalang penubuhan Malaysia.', '2', 'Mengenal pasti bantahan SUPP di Sarawak, Konfrontasi Indonesia, dan tuntutan Filipina ke atas Sabah.', '{"bgImage": "../assets/gameAsset/background/bilik_strategi_keselamatan.png", "hotspots": [{"name": "Minit Bantahan Parti SUPP Sarawak yang menolak gabungan demi merdeka berasingan", "top": "28%", "left": "18%"}, {"name": "Perisytiharan Konfrontasi Indonesia: slogan Ganyang Malaysia (20 Januari 1963)", "top": "55%", "left": "62%"}, {"name": "Dokumen Tuntutan Rasmi Filipina ke atas Wilayah Sabah", "top": "72%", "left": "35%"}], "aftermath": "Tanpa bukti yang jelas, setiap pihak menuduh pihak lain. Rundingan terhenti dan tekanan di sempadan bertambah.", "turns": [{"after": 3, "options": [{"text": "Biar PBB bertanya kepada rakyat Borneo sendiri, bukan kita yang menjawab bagi pihak mereka.", "isCorrect": true, "reaction": "Itu yang paling sukar dipertikaikan, Tunku: suara rakyat sendiri."}, {"text": "Biar Parlimen Tanah Melayu mengundi bagi pihak rakyat Borneo.", "isCorrect": false, "reaction": "Itu sama seperti kita menjawab bagi pihak mereka, Tunku. Indonesia akan terus membantah."}, {"text": "Biar tentera kita menjaga sempadan dahulu, kemudian baru berunding dengan PBB.", "isCorrect": false, "reaction": "Tentera boleh menjaga sempadan, Tunku, tetapi tuntutan Filipina dan SUPP tidak akan hilang dengan senjata."}], "clue": "Ghazali mencadangkan PBB bertanya kepada rakyat Borneo sendiri."}]}'),
(5, 'e1_n1_s5', 'Laporan Pengesahan PBB', 'Nyahkod kandungan laporan rasmi UNMM yang diterbitkan pada 14 September 1963.', '5', 'Memahami fungsi Perjanjian London 1963 dan pengesahan rasmi UNMM/PBB.', '{"clueText": "Siasatan bebas PBB di Sabah dan Sarawak mengesahkan bahawa majoriti rakyat menyokong pembentukan Malaysia secara bebas dan demokratik.", "options": [{"text": "Majoriti rakyat Sabah dan Sarawak menyokong Malaysia secara bebas, tanpa paksaan.", "isCorrect": true}, {"text": "Majoriti rakyat Sabah dan Sarawak menyokong Malaysia, tetapi hanya selepas ditekan pemimpin.", "isCorrect": false, "consequence": "Jika laporan ini dianggap disahkan oleh tekanan, Indonesia menggunakannya untuk menolak keputusan PBB. Pengesahan antarabangsa goyah."}, {"text": "Majoriti rakyat Sabah menyokong, tetapi Sarawak meminta pungutan suara baharu.", "isCorrect": false, "consequence": "Jika kau membaca laporan dengan salah, perundingan dibuka semula untuk Sarawak. Pemasyhuran tertangguh dan Konfrontasi bertambah kuat."}], "aftermath": "Laporan yang salah dibaca menimbulkan kekeliruan. Indonesia dan Filipina menggunakannya untuk mempersoalkan Malaysia di PBB.", "turns": [{"after": 3, "options": [{"text": "Rakyat Sabah dan Sarawak sendiri.", "isCorrect": true, "reaction": "Itulah sebab misi ini wujud, Tunku, dan sebab laporannya akan dipercayai."}, {"text": "Wakil PBB bersama Kerajaan Tanah Melayu.", "isCorrect": false, "reaction": "Kalau kita turut menentukan, misi PBB tiada gunanya, Tunku. Indonesia dan Filipina menang hujah."}, {"text": "Kerajaan British, kerana perjanjian sudah ditandatangani.", "isCorrect": false, "reaction": "Perjanjian sudah ditandatangani, Tunku, tetapi PBB mahu mendengar rakyat, bukan London."}], "clue": "Ghazali menyebut Michelmore bertanya kepada rakyat Borneo, bukan kepada kita."}]}'),
(6, 'e1_n1_s6', 'Susun Kronologi Pembentukan Malaysia', 'Susun peristiwa penting pembentukan Malaysia dari awal hingga hari pemasyhuran mengikut urutan yang betul.', '1', 'Menyusun ikhtisar kronologi peristiwa Pembentukan Malaysia (1961–1963).', '{"timelineItems": [{"id": 1, "year": "27 Mei 1961", "text": "Tunku Abdul Rahman mengumumkan cadangan Pembentukan Malaysia di Hotel Adelphi Singapura", "why": "Semuanya bermula apabila Tunku mengumumkan cadangan itu di hadapan wartawan."}, {"id": 2, "year": "23 Julai 1961", "text": "Penubuhan Jawatankuasa Setia Kawan Malaysia JSKM", "why": "Selepas cadangan diumumkan, rakyat Borneo perlu faham maksud Malaysia, jadi JSKM ditubuhkan untuk menerangkannya."}, {"id": 3, "year": "21 Jun 1962", "text": "Laporan Suruhanjaya Cobbold diserahkan mengesahkan sokongan 2/3 rakyat Borneo", "why": "Penerangan sahaja tidak cukup. Suruhanjaya Cobbold turun mendengar rakyat, dan laporannya mengesahkan sokongan."}, {"id": 4, "year": "9 Julai 1963", "text": "Perjanjian Malaysia ditandatangani di Marlborough House London", "why": "Setelah sokongan rakyat disahkan dan Perlembagaan dirangka melalui JAK, perjanjian boleh ditandatangani di London."}, {"id": 5, "year": "16 September 1963", "text": "Pemasyhuran Rasmi Malaysia diisytiharkan secara serentak", "why": "Selepas perjanjian dan siasatan PBB, tiada lagi halangan, maka Malaysia diisytiharkan."}], "aftermath": "Peristiwa disusun dengan salah, dan sejarah yang kau baca di Stadium Merdeka tidak lagi bersambung. Kau perlu menyusunnya semula.", "turns": [{"after": 4, "options": [{"text": "Supaya setiap wilayah dilihat sama taraf sebagai rakan.", "isCorrect": true, "reaction": "Betul, Tunku. Empat tempat, satu hari, satu negara."}, {"text": "Supaya Kuala Lumpur dilihat sebagai pusat utama dan yang lain mengikut.", "isCorrect": false, "reaction": "Kalau begitu, Sarawak dilihat sebagai pengikut, Tunku. Itu yang kami tidak mahu."}, {"text": "Supaya wartawan asing tidak sempat membuat liputan di setiap bandar.", "isCorrect": false, "reaction": "Kita mahu dunia melihat, Tunku. Serentak bermakna semua orang boleh menyaksikannya."}], "clue": "Kalong berkata Sarawak mahu dilihat sebagai rakan, bukan pengikut. Fikirkan mengapa semua tempat membaca serentak."}]}'),
(7, 'e1_n2_s1', 'Menilai Kebajikan Rakyat Borneo', 'Bantu Donald Stephens menjelaskan faktor utama mengapa Sabah dan Sarawak perlu mempertimbangkan pembentukan Malaysia.', '3', 'Memahami faktor pembentukan Malaysia dari perspektif keselamatan dan pembangunan sosioekonomi Borneo.', '{"prompt": "Rakyat Borneo bertanya kepada kau: apakah faedah utama yang diperoleh Sabah dan Sarawak melalui pembentukan Malaysia?", "options": [{"text": "Kemerdekaan lebih awal, perlindungan daripada komunis, keseimbangan kaum dan kemajuan ekonomi.", "isCorrect": true}, {"text": "Kemerdekaan lebih awal, perlindungan daripada komunis, penguasaan wilayah dan kemajuan ekonomi.", "isCorrect": false, "consequence": "Rakyat menganggap kau mahu Borneo dikuasai pihak lain. Perhimpunan menjadi gempar dan sokongan merosot."}, {"text": "Kemerdekaan lebih lewat, perlindungan daripada British, keseimbangan kaum dan kemajuan ekonomi.", "isCorrect": false, "consequence": "Rakyat bertanya mengapa mahu menyertai Malaysia jika kemerdekaan bertambah lewat. Mereka menolak hujah kau serta-merta."}], "aftermath": "Rakyat menilai kau sebagai pemimpin yang tidak menjaga kebajikan mereka. Perhimpunan bersurai dengan rasa curiga.", "turns": [{"after": 3, "options": [{"text": "Dengar pandangan rakyat dan timbang untung ruginya dahulu.", "isCorrect": true, "reaction": "Itu cara orang yang menghormati tanahnya, Donald. Kita dengar, kita timbang, baru kita bercakap."}, {"text": "Terima segera supaya Sabah cepat merdeka dan tidak ketinggalan.", "isCorrect": false, "reaction": "Tergesa-gesa begini, Donald, rakyat akan rasa tidak diajak berbincang."}, {"text": "Tolak segera sehingga Tunku menjelaskan semua syaratnya secara bertulis.", "isCorrect": false, "reaction": "Menolak tanpa mendengar rakyat sama sahaja dengan diam ketika orang lain menentukan nasib kita, Donald."}], "clue": "Tun Jugah bimbang hanya diberitahu, bukan ditanya. Jadi mulakan dengan mendengar rakyat."}]}'),
(8, 'e1_n2_s2', 'Padanan Tokoh dan Jawatankuasa Borneo', 'Padankan tokoh pejuang Borneo dan jawatankuasa tinjauan dengan peranannya yang betul.', '4', 'Mengenal pasti peranan Donald Stephens, Tun Temenggung Jugah, JSKM, dan Suruhanjaya Cobbold.', '{"pairs": [{"text": "Donald Stephens", "pair": 1}, {"text": "Pengerusi JSKM yang memimpin penerangan pembentukan Malaysia di Borneo", "pair": 1}, {"text": "Tun Temenggung Jugah", "pair": 2}, {"text": "Pemimpin masyarakat Iban Sarawak yang menegaskan perlindungan hak adat tempatan", "pair": 2}, {"text": "JSKM (23 Julai 1961)", "pair": 3}, {"text": "Jawatankuasa penerangan awal bagi meyakinkan pemimpin dan rakyat Borneo", "pair": 3}, {"text": "Laporan Cobbold (21 Jun 1962)", "pair": 4}, {"text": "Mengesahkan dua pertiga (2/3) penduduk Sabah dan Sarawak menyokong Malaysia", "pair": 4}], "aftermath": "Rakyat tidak lagi mempercayai suruhanjaya. Kampung demi kampung berhenti bercakap kepada Cobbold.", "turns": [{"after": 3, "options": [{"text": "Ya, Suruhanjaya Cobbold datang untuk mencatat pandangan anda.", "isCorrect": true, "reaction": "Betul, Donald, dan sebab itu laporan mereka nanti dipercayai."}, {"text": "Ya, tetapi hanya pandangan pemimpin kampung yang akan dicatat.", "isCorrect": false, "reaction": "Rakyat biasa pun mahu didengar, Donald. Kalau tidak, mereka berhenti percaya."}, {"text": "Tidak pasti, kerana keputusan Malaysia mungkin sudah dibuat di London.", "isCorrect": false, "reaction": "Jawapan begitu menguatkan syak mereka, Donald. Jangan biarkan mereka berhenti bercakap."}], "clue": "Tun Jugah berkata Cobbold datang untuk mendengar rakyat. Itulah tujuannya."}]}'),
(9, 'e1_n2_s3', 'Keputusan Hak Keistimewaan Borneo', 'Bantu Donald Stephens dan Tun Temenggung Jugah memastikan tuntutan hak keistimewaan Borneo diterima dalam JAK.', '3', 'Memahami perkara utama dalam Hak 20 Perkara Sabah dan draf Perlembagaan Malaysia oleh JAK.', '{"prompt": "Apakah tuntutan utama yang diperjuangkan oleh pemimpin Borneo untuk dimasukkan ke dalam Perlembagaan Malaysia?", "options": [{"text": "Hak imigresen, agama, bahasa dan perkhidmatan awam tempatan dilindungi dalam Perlembagaan.", "isCorrect": true}, {"text": "Hak imigresen, agama, bahasa dan perkhidmatan awam tempatan dijanjikan secara lisan oleh pemimpin.", "isCorrect": false, "consequence": "Janji lisan hilang apabila pemimpin bertukar. Beberapa tahun kemudian rakyat Borneo tidak dapat menuntut hak mereka."}, {"text": "Hak imigresen, agama, bahasa dan perkhidmatan awam tempatan dipindahkan ke Kerajaan Pusat sahaja.", "isCorrect": false, "consequence": "Kuasa ke atas tanah dan imigresen beralih ke Kuala Lumpur. Rakyat Borneo merasa kehilangan kawalan atas tanah mereka."}], "aftermath": "Tuntutan Borneo tidak termasuk dalam teks akhir. Apabila rakyat membacanya, mereka merasa dikhianati.", "turns": [{"after": 3, "options": [{"text": "Perlindungan hak imigresen, agama, bahasa dan perkhidmatan awam, ditulis dalam Perlembagaan.", "isCorrect": true, "reaction": "Itulah cara ia menjadi undang-undang, Donald. Kita tulis satu demi satu."}, {"text": "Perlindungan hak imigresen, agama, bahasa dan perkhidmatan awam, dicatat dalam surat sokongan.", "isCorrect": false, "reaction": "Surat sokongan mudah dilupakan, Donald. Itu yang Tun Jugah takutkan."}, {"text": "Perlindungan hak imigresen, agama, bahasa dan perkhidmatan awam, dijanjikan oleh pemimpin lisan.", "isCorrect": false, "reaction": "Aku percaya, Donald, tetapi rakyat memerlukan jaminan bertulis, bukan hanya kepercayaan."}], "clue": "Tun Jugah tidak mahu tuntutan hanya disebut dalam lampiran. Ia mesti ada dalam Perlembagaan."}]}'),
(10, 'e1_n2_s4', 'Cari Bukti Ancaman di Borneo', 'Cari dokumen bantahan politik tempatan dan bukti pencerobohan luar di sempadan Borneo.', '2', 'Mengenal pasti cabaran pembentukan Malaysia di Borneo (SUPP, Konfrontasi Indonesia, tuntutan Filipina).', '{"bgImage": "../assets/gameAsset/background/bilik_strategi_keselamatan.png", "hotspots": [{"name": "Dokumen Bantahan Parti SUPP Sarawak yang menolak cadangan Pembentukan Malaysia", "top": "28%", "left": "18%"}, {"name": "Laporan Pencerobohan Tentera Konfrontasi Indonesia di Sempadan Sabah dan Sarawak", "top": "55%", "left": "62%"}, {"name": "Nota Tuntutan Filipina ke atas Wilayah Sabah", "top": "72%", "left": "35%"}], "aftermath": "Tanpa bukti, dakwaan SUPP, Indonesia dan Filipina tidak dapat dijawab. Rakyat mula ragu-ragu.", "turns": [{"after": 3, "options": [{"text": "Tunjukkan bahawa hak Borneo sudah ditulis dalam Perlembagaan melalui JAK.", "isCorrect": true, "reaction": "Itu jawapan yang boleh dipegang, Donald. Hak yang tertulis tidak mudah dipadam."}, {"text": "Tunjukkan bahawa tentera kita cukup kuat menghadapi Konfrontasi dan tuntutan Filipina.", "isCorrect": false, "reaction": "Kekuatan tidak menjawab kebimbangan SUPP, Donald. Mereka mahu jaminan hak, bukan senjata."}, {"text": "Tunjukkan bahawa SUPP tidak berhak bersuara kerana mereka pembangkang.", "isCorrect": false, "reaction": "Menyenyapkan SUPP hanya menguatkan kebimbangan mereka, Donald."}], "clue": "Kalong berkata SUPP mesti dijawab dengan hak yang sudah ditulis dalam Perlembagaan melalui JAK."}]}'),
(11, 'e1_n2_s5', 'Nyahkod Hasil Tinjauan PBB', 'Nyahkod kenyataan Laporan UNMM yang diterbitkan pada 14 September 1963 di Borneo.', '5', 'Memahami peranan Perjanjian London 1963 dan pengesahan rasmi PBB di Sabah dan Sarawak.', '{"clueText": "Penilaian bebas Suruhanjaya PBB mengesahkan bahawa majoriti rakyat Sabah dan Sarawak tetap teguh memilih untuk menyertai Malaysia.", "options": [{"text": "Majoriti rakyat Sabah dan Sarawak menyokong Malaysia, dan pilihan itu dibuat secara bebas.", "isCorrect": true}, {"text": "Majoriti rakyat Sabah dan Sarawak menolak Malaysia, dan pilihan itu dibuat secara bebas.", "isCorrect": false, "consequence": "Jika laporan menolak Malaysia, Perjanjian London terbatal dan rundingan dua tahun hilang. Tetapi itu bukan laporan UNMM."}, {"text": "Majoriti rakyat Sabah dan Sarawak menyokong Malaysia, tetapi mahu kekal di bawah British dahulu.", "isCorrect": false, "consequence": "Jika Borneo kekal di bawah British, kemerdekaan tertangguh sekali lagi. Pemasyhuran 16 September tidak dapat diteruskan."}], "aftermath": "Laporan yang tidak jujur tidak dipercayai sesiapa. Indonesia dan Filipina menggunakannya sebagai hujah menentang Malaysia.", "turns": [{"after": 3, "options": [{"text": "Menjawab dengan jujur, mengikut kehendak hati sendiri.", "isCorrect": true, "reaction": "Itu yang kami mahu, Donald. Kejujuran kita ialah bukti terbaik."}, {"text": "Menjawab seperti yang diminta pemimpin supaya perjanjian cepat disahkan.", "isCorrect": false, "reaction": "Kalau begitu, misi ini membuang masa dan Indonesia berkata kita memaksa rakyat, Donald."}, {"text": "Menjawab secara umum tanpa menyebut pendirian sendiri.", "isCorrect": false, "reaction": "Jawapan kabur menjadikan suara kita tidak dikira, Donald. Jangan biarkan orang lain bercakap bagi pihak kita."}], "clue": "Kalong berkata Michelmore mahu mendengar sendiri daripada rakyat, jadi jawapan mesti datang daripada hati sendiri."}]}'),
(12, 'e1_n2_s6', 'Susun Garis Masa Pemasyhuran Borneo', 'Susun peristiwa penting perjalanan pembentukan Malaysia mengikut urutan kronologi dari perspektif Borneo.', '1', 'Menyusun ikhtisar urutan kronologi Pembentukan Malaysia (1961–1963).', '{"timelineItems": [{"id": 1, "year": "27 Mei 1961", "text": "Pengumuman Cadangan Malaysia oleh Tunku Abdul Rahman di Singapura", "why": "Pengumuman Tunku membuka peluang kepada Borneo untuk bersuara."}, {"id": 2, "year": "23 Julai 1961", "text": "Penubuhan Jawatankuasa Setia Kawan Malaysia JSKM di bawah Donald Stephens", "why": "Donald Stephens mengetuai JSKM supaya rakyat Sabah dan Sarawak memahami cadangan itu sebelum menjawab."}, {"id": 3, "year": "21 Jun 1962", "text": "Penyerahan Laporan Suruhanjaya Cobbold mengesahkan sokongan 2/3 rakyat Borneo", "why": "Kemudian Cobbold mendengar rakyat sendiri, dan laporannya menunjukkan dua pertiga menyokong."}, {"id": 4, "year": "9 Julai 1963", "text": "Penandatanganan Perjanjian Malaysia di Marlborough House London", "why": "Dengan sokongan itu dan hak Borneo dijamin dalam Perlembagaan, perjanjian ditandatangani di London."}, {"id": 5, "year": "16 September 1963", "text": "Pembacaan Pemasyhuran Malaysia di Kota Kinabalu dan Kuching", "why": "Selepas UNMM mengesahkan pilihan rakyat, pemimpin Borneo membacakan Pemasyhuran di Kota Kinabalu dan Kuching."}], "aftermath": "Urutan peristiwa terganggu, dan kisah Pemasyhuran tidak lagi mengalir. Kau perlu menyusunnya semula.", "turns": [{"after": 4, "options": [{"text": "Donald Stephens di Sabah, Stephen Kalong Ningkan di Sarawak.", "isCorrect": true, "reaction": "Betul, Donald. Dua tempat, satu hari, satu negara."}, {"text": "Tun Mustapha di Sabah, Stephen Kalong Ningkan di Sarawak.", "isCorrect": false, "reaction": "Tun Mustapha berdiri bersama kita, Donald, tetapi bukan dia yang membacanya di Sabah."}, {"text": "Donald Stephens di Sabah, Tun Jugah di Sarawak.", "isCorrect": false, "reaction": "Tun Jugah menyokong kita, Donald, tetapi bukan dia yang membacanya di Kuching."}], "clue": "Kalong berkata dia membacanya di Kuching, dan kau di Kota Kinabalu."}]}'),
(13, 'e1_n3_s1', 'Strategi Benteng Keselamatan', 'Bantu Tun Ghazali Shafie menggariskan faktor keselamatan dan kestabilan utama pembentukan Malaysia.', '3', 'Memahami faktor pembentukan Malaysia iaitu membendung komunis, keseimbangan kaum, kemerdekaan, dan sosioekonomi.', '{"prompt": "Apakah pertimbangan keselamatan utama yang menjadikan pembentukan Malaysia sangat mendesak?", "options": [{"text": "Membendung komunis di Singapura dan Sarawak serta menjamin kestabilan politik rantau.", "isCorrect": true}, {"text": "Membendung komunis di Singapura dan Sarawak dengan bantuan tentera asing yang kekal.", "isCorrect": false, "consequence": "Jika tentera asing menetap, kedaulatan hilang sebelum Malaysia terbentuk. Tunku menolak nasihat itu serta-merta."}, {"text": "Membendung komunis di Singapura dan Sarawak dengan mengurangkan kerjasama antara wilayah.", "isCorrect": false, "consequence": "Jika kerjasama antara wilayah dikurangkan, komunis menembusi jurang itu dan ancaman bertambah besar."}], "aftermath": "Nasihat kau tidak lengkap. Pelan keselamatan tidak merangkumi semua ancaman, dan jurang itu dimanfaatkan pihak lawan.", "turns": [{"after": 3, "options": [{"text": "Membendung komunis, menjaga kaum, mempercepat kemerdekaan dan memajukan ekonomi.", "isCorrect": true, "reaction": "Tepat, Ghazali. Empat sebab, bukan satu."}, {"text": "Membendung komunis, menjaga kaum, melambatkan kemerdekaan dan memajukan ekonomi.", "isCorrect": false, "reaction": "Melambatkan kemerdekaan bukan sebab kita, Ghazali. Borneo akan menolak sebelum sempat berunding."}, {"text": "Membendung komunis, menjaga British, mempercepat kemerdekaan dan memajukan ekonomi.", "isCorrect": false, "reaction": "Kita bukan menjaga British, Ghazali. Hujah itu mudah dipatahkan Indonesia."}], "clue": "Tunku menyebut empat sebab: komunis, kaum, kemerdekaan Borneo dan ekonomi. Sebutkan kesemuanya."}]}'),
(14, 'e1_n3_s2', 'Padanan Misi Tinjauan Cobbold', 'Padankan JSKM, Suruhanjaya Cobbold, laporannya dan ahli tempatan dengan maklumat yang betul.', '4', 'Mengenal pasti peranan JSKM dan Suruhanjaya Cobbold.', '{"pairs": [{"text": "JSKM (23 Julai 1961)", "pair": 1}, {"text": "Jawatankuasa penerangan awal di bawah pimpinan Donald Stephens", "pair": 1}, {"text": "Suruhanjaya Cobbold (17 Jan 1962)", "pair": 2}, {"text": "Meninjau pandangan rakyat Sabah dan Sarawak di kampung-kampung", "pair": 2}, {"text": "Laporan Cobbold (21 Jun 1962)", "pair": 3}, {"text": "Dua pertiga menyokong; selebihnya mahu merdeka dahulu", "pair": 3}, {"text": "Ghazali Shafie dan Wong Pow Nee", "pair": 4}, {"text": "Ahli tempatan dalam Suruhanjaya Cobbold", "pair": 4}], "aftermath": "Misi dan jawatankuasa disalah padankan, dan laporan menjadi kelam-kabut. Tiada siapa pasti siapa bertanggungjawab ke atas apa.", "turns": [{"after": 4, "options": [{"text": "Menjawab keraguan itu dengan menulis jaminan hak mereka dalam Perlembagaan.", "isCorrect": true, "reaction": "Betul, Ghazali. Keraguan hilang apabila ada jaminan bertulis, bukan janji kosong."}, {"text": "Menjawab keraguan itu dengan janji lisan daripada Perdana Menteri sahaja.", "isCorrect": false, "reaction": "Janji lisan tidak menenangkan keraguan, Ghazali. Mereka mahukan bukti tertulis."}, {"text": "Menangguhkan Malaysia sehingga seluruh rakyat Borneo menyokong sepenuhnya.", "isCorrect": false, "reaction": "Jika semua mesti setuju, Malaysia tidak akan terbentuk, Ghazali. Tetapi suara yang ragu mesti dihormati."}], "clue": "Kau sendiri berkata keraguan mesti dijawab, bukan disenyapkan. JAK menulis Perlembagaan, jadi jawapannya ditulis di sana."}]}'),
(15, 'e1_n3_s3', 'Jaminan Hak Borneo dalam Perlembagaan', 'Bantu Tun Ghazali Shafie memastikan hak Sabah dan Sarawak dijamin dalam Perlembagaan melalui JAK.', '3', 'Memahami peranan JAK serta Hak 20 Perkara Sabah dan 18 Perkara Sarawak.', '{"prompt": "Seorang wakil Borneo bertanya kepada kau: bagaimana Hak 20 Perkara Sabah dan 18 Perkara Sarawak dapat dilindungi dengan kukuh?", "options": [{"text": "Hak itu ditulis dalam Perlembagaan Malaysia sebagai undang-undang yang mengikat.", "isCorrect": true}, {"text": "Hak itu dicatat sebagai janji lisan pemimpin pada hari penandatanganan perjanjian.", "isCorrect": false, "consequence": "Janji lisan hilang apabila pemimpin bertukar. Beberapa tahun kemudian rakyat Borneo tidak dapat menuntut hak mereka."}, {"text": "Hak itu ditangguhkan sehingga selepas Malaysia terbentuk dan kerajaan baharu bersidang.", "isCorrect": false, "consequence": "Selepas Malaysia terbentuk, Borneo tiada kuasa berunding lagi. Pemimpin Sabah dan Sarawak menarik sokongan."}], "aftermath": "Hak yang tidak ditulis hilang bersama pemimpin yang berjanji. Wakil Borneo bangun dan meninggalkan dewan.", "turns": [{"after": 3, "options": [{"text": "Menulis jaminan itu dalam Perlembagaan sebagai undang-undang.", "isCorrect": true, "reaction": "Itu maksud kami, Ghazali. Janji boleh dilupa, undang-undang tertulis tidak."}, {"text": "Menerima janji lisan para pemimpin pada hari penandatanganan itu.", "isCorrect": false, "reaction": "Janji lisan hilang bersama orang yang berjanji, Ghazali. Kami sudah banyak melihatnya."}, {"text": "Menangguhkan perbincangan sehingga selepas Malaysia terbentuk nanti.", "isCorrect": false, "reaction": "Selepas itu rakyat kami tiada kuasa berunding lagi, Ghazali. Itu bukan jalan yang adil."}], "clue": "Tun Jugah berkata adat mesti ditulis, bukan janji lisan. Hak yang tertulis dalam Perlembagaan menjadi undang-undang."}]}'),
(16, 'e1_n3_s4', 'Cari Bukti Ancaman Keselamatan', 'Cari dokumen bukti tentangan dalaman dan pencerobohan luaran terhadap Malaysia.', '2', 'Mengenal pasti bantahan SUPP, Konfrontasi Indonesia, dan tuntutan Filipina ke atas Sabah.', '{"bgImage": "../assets/gameAsset/background/perancangan_pembentukan_malaysia.png", "hotspots": [{"name": "Risalah Bantahan Parti SUPP Sarawak yang menolak cadangan Persekutuan", "top": "28%", "left": "18%"}, {"name": "Perisytiharan Konfrontasi Indonesia (Ganyang Malaysia) pada 20 Januari 1963", "top": "55%", "left": "62%"}, {"name": "Teks Tuntutan Filipina ke atas Wilayah Sabah", "top": "72%", "left": "35%"}], "aftermath": "Ancaman yang tidak dikenal pasti tidak dapat dijawab. Sempadan terdedah dan rundingan diplomasi terganggu.", "turns": [{"after": 3, "options": [{"text": "Konfrontasi, kerana ia ancaman keselamatan sebenar di sempadan.", "isCorrect": true, "reaction": "Betul, Ghazali. Keselamatan dahulu, baru diplomasi boleh berjalan."}, {"text": "SUPP, kerana ia pertikaian dalam negeri yang boleh merebak.", "isCorrect": false, "reaction": "SUPP penting dan boleh dirunding, Ghazali. Tetapi tentera di sempadan tidak menunggu."}, {"text": "Filipina, kerana tuntutannya boleh menjejaskan kedaulatan Sabah.", "isCorrect": false, "reaction": "Tuntutan itu serius, Ghazali, tetapi ia diplomasi. Ancaman di sempadan lebih mendesak."}], "clue": "Kau sendiri berkata Konfrontasi ialah ancaman keselamatan, sementara dua lagi boleh dijawab dengan perundingan."}]}'),
(17, 'e1_n3_s5', 'Nyahkod Keputusan Misi PBB', 'Nyahkod penemuan rasmi Laporan UNMM yang dikeluarkan pada 14 September 1963.', '5', 'Memahami peranan Perjanjian London 1963 dan pengesahan rasmi UNMM/PBB.', '{"clueText": "Siasatan PBB mengesahkan bahawa majoriti rakyat Sabah dan Sarawak menyokong pembentukan Malaysia secara demokratik, sekali gus menolak dakwaan Indonesia dan Filipina.", "options": [{"text": "Majoriti rakyat Sabah dan Sarawak menyokong Malaysia, dan PBB mengesahkannya.", "isCorrect": true}, {"text": "Majoriti rakyat Sabah dan Sarawak menyokong Malaysia, tetapi PBB menolak mengesahkannya.", "isCorrect": false, "consequence": "Jika PBB tidak mengesahkan, Indonesia dan Filipina menggunakannya untuk menyerang Malaysia. Pemasyhuran tertangguh."}, {"text": "Majoriti rakyat Sabah dan Sarawak mahu bergabung dengan Indonesia, dan PBB mengesahkannya.", "isCorrect": false, "consequence": "Jika Borneo bergabung dengan Indonesia, negara baharu itu hilang sebelum lahir. Tetapi itu bukan penemuan laporan."}], "aftermath": "Laporan dicurigai kerana disaring oleh pihak berkuasa. Indonesia menolaknya, dan pengesahan antarabangsa goyah.", "turns": [{"after": 3, "options": [{"text": "Biarkan mereka bertemu sesiapa sahaja sendiri tanpa kita.", "isCorrect": true, "reaction": "Itu nasihat yang baik, Ghazali. Laporan yang dipercayai ialah laporan yang tidak kita sentuh."}, {"text": "Temani pegawai UNMM ke setiap pertemuan untuk menjawab soalan.", "isCorrect": false, "reaction": "Kalau kita ada, rakyat berhati-hati, Ghazali, dan Indonesia berkata kita memengaruhi mereka."}, {"text": "Sediakan senarai orang yang akan ditemui oleh pegawai UNMM.", "isCorrect": false, "reaction": "Senarai itu menjadikan laporan kita yang tulis, Ghazali, bukan PBB."}], "clue": "Tun Razak berkata PBB mahu pegawainya bebas bertemu sesiapa tanpa kita campur tangan."}]}'),
(18, 'e1_n3_s6', 'Kronologi Keselamatan dan Kedaulatan', 'Susun peristiwa penting perjalanan pembentukan Malaysia mengikut urutan kronologi yang betul dari awal hingga kemuncak pemasyhuran.', '1', 'Menyusun ikhtisar urutan kronologi Pembentukan Malaysia (1961–1963).', '{"timelineItems": [{"id": 1, "year": "27 Mei 1961", "text": "Pengumuman Cadangan Malaysia oleh Tunku Abdul Rahman di Hotel Adelphi Singapura", "why": "Ancaman komunis menjadi sebab utama cadangan ini diumumkan."}, {"id": 2, "year": "23 Julai 1961", "text": "Penubuhan Jawatankuasa Setia Kawan Malaysia JSKM", "why": "Rakyat perlu diyakinkan untuk menolak pengaruh yang mengancam keselamatan, jadi JSKM ditubuhkan."}, {"id": 3, "year": "21 Jun 1962", "text": "Laporan Suruhanjaya Cobbold diserahkan mengesahkan sokongan 2/3 rakyat Borneo", "why": "Cobbold menilai suara sebenar rakyat, dan laporannya mengesahkan sokongan walaupun ada bantahan."}, {"id": 4, "year": "9 Julai 1963", "text": "Perjanjian Malaysia ditandatangani di Marlborough House London", "why": "Selepas bantahan SUPP dijawab dan Konfrontasi dihadapi, perjanjian ditandatangani di London."}, {"id": 5, "year": "16 September 1963", "text": "Pengisytiharan Rasmi Pemasyhuran Malaysia secara serentak", "why": "Dengan keselamatan terjamin dan PBB mengesahkan sokongan, Malaysia diisytiharkan secara serentak."}], "aftermath": "Susunan hari Pemasyhuran terganggu. Empat bandar tidak serentak dan keselamatan majlis goyah.", "turns": [{"after": 3, "options": [{"text": "Memastikan majlis berjalan lancar tanpa gangguan keselamatan.", "isCorrect": true, "reaction": "Betul, Ghazali. Tugas yang jarang dipuji, tetapi tanpanya tiada majlis."}, {"text": "Berdiri di sebelah Tunku supaya diambil gambar bersama.", "isCorrect": false, "reaction": "Kamera tidak menjaga sempadan, Ghazali. Kerja kita di belakang tabir."}, {"text": "Mengubah jadual majlis supaya mula lebih awal di semua bandar.", "isCorrect": false, "reaction": "Empat bandar sudah diselaraskan, Ghazali. Jika satu berubah, yang lain terkacau."}], "clue": "Satu kesilapan masa akan dilihat semua orang, jadi keselamatan dan susunan ialah tugas utama kau."}]}');
INSERT INTO LearningSupport (questID, sceneID, supportType, hint, explanation, feedback) VALUES
(NULL, 'e1_n1_s1', 'hint', 'Tunku Abdul Rahman berdiri di hadapan wartawan tempatan dan antarabangsa pada 27 Mei 1961. Di sebalik cadangan ini, terdapat sejarah idea daripada Lord Brassey (1887), Ibrahim Yaakob (1938), Malcolm MacDonald (1951), dan ucapan awal Tunku pada 1955.', NULL, NULL),
(1, NULL, 'hint', 'Fikirkan ancaman komunis di Singapura dan Sarawak serta faedah kemerdekaan dan pembangunan ekonomi bersama.', '27 Mei 1961, Hotel Adelphi. Aku mengumumkan gagasan Malaysia kepada dunia. Empat sebab menyokongnya: membendung komunis, mengimbangi kaum, mempercepat kemerdekaan Borneo dan memajukan ekonomi.', 'Syabas! Penerangan yang berasas ini berhasil meyakinkan perwakilan media dan memulakan langkah rasmi pembentukan.'),
(NULL, 'e1_n1_s2', 'hint', 'Selepas penubuhan Jawatankuasa Setia Kawan Malaysia (JSKM) pada 23 Julai 1961 di bawah Donald Stephens, Suruhanjaya Cobbold ditubuhkan pada 17 Januari 1962 bersama ahli tempatan seperti Tun Muhammad Ghazali Shafie dan Tan Sri Wong Pow Nee.', NULL, NULL),
(2, NULL, 'hint', 'Gabungkan kumpulan yang menyokong penuh dan menyokong bersyarat untuk mendapatkan nisbah majoriti dua pertiga.', 'JSKM (23 Julai 1961, Donald Stephens) menerangkan Malaysia. Cobbold (17 Januari 1962; Ghazali dan Wong Pow Nee) mendengar rakyat. Laporan 21 Jun 1962: dua pertiga menyokong, ada bersyarat.', 'Syabas! Analisis anda membuktikan sokongan majoriti rakyat Borneo terhadap gagasan penyatuan ini.'),
(NULL, 'e1_n1_s3', 'hint', 'Jawatankuasa Antara Kerajaan (JAK) ditubuhkan pada 30 Ogos 1962 dipengerusikan oleh Lord Lansdowne dan Tun Abdul Razak untuk merangka perlembagaan dan memasukkan peruntukan Hak 20 Perkara Sabah serta tuntutan Sarawak.', NULL, NULL),
(3, NULL, 'hint', 'JAK dipengerusikan oleh Lansdowne dan Tun Razak untuk memasukkan Hak 20 Perkara ke dalam Perlembagaan.', '30 Ogos 1962: JAK (Lord Lansdowne dan Tun Razak) menulis Hak 20 Perkara Sabah dan 18 Perkara Sarawak dalam Perlembagaan. Janji lisan boleh dilupa, undang-undang tertulis tidak.', 'Tepat sekali! Penggubalan syarat ini menjamin keadilan dan persetujuan bersama antara wilayah.'),
(NULL, 'e1_n1_s4', 'hint', 'Tunku Abdul Rahman dan Tun Abdul Razak meneliti laporan bantahan parti Sarawak United People''s Party (SUPP), pengisytiharan Konfrontasi Indonesia (Ganyang Malaysia) pada 20 Januari 1963, serta tuntutan Filipina ke atas Sabah.', NULL, NULL),
(4, NULL, 'hint', 'Cari dokumen bantahan politik SUPP Sarawak, kenyataan Konfrontasi Indonesia, dan surat tuntutan Filipina.', 'Malaysia dicabar tiga pihak: SUPP yang mahu merdeka dahulu, Konfrontasi Indonesia (20 Januari 1963) dan tuntutan Filipina ke atas Sabah. Aku memilih diplomasi, bukan kekerasan.', 'Cemerlang! Bukti cabaran berjaya dikesan bagi membolehkan langkah diplomasi strategik diambil.'),
(NULL, 'e1_n1_s5', 'hint', 'Perjanjian Malaysia ditandatangani pada 9 Julai 1963 di London. Ekoran bantahan Indonesia dan Filipina, PBB menubuhkan United Nations Malaysia Mission (UNMM) pada 12 Ogos 1963 di bawah Laurence Michelmore.', NULL, NULL),
(5, NULL, 'hint', 'Laporan UNMM mengesahkan semula dapatan Suruhanjaya Cobbold bahawa majoriti rakyat Borneo menyokong Malaysia.', '9 Julai 1963: Perjanjian Malaysia ditandatangani di London. UNMM (12 Ogos 1963, Michelmore) bertanya kepada rakyat Borneo. Laporan 14 September mengesahkan sokongan; 31 Ogos ditangguh ke 16 September.', 'Syabas! Pengesahan antarabangsa ini mematahkan hujah penentang luaran secara muktamad.'),
(NULL, 'e1_n1_s6', 'hint', 'Tunku Abdul Rahman berdiri megah membacakan Teks Pemasyhuran Malaysia pada 16 September 1963, dilangsungkan serentak di Kuala Lumpur, Kuching, Kota Kinabalu, dan Singapura.', NULL, NULL),
(6, NULL, 'hint', 'Bermula dari Cadangan 1961, JSKM, Laporan Cobbold 1962, Perjanjian London Julai 1963, dan Pemasyhuran 16 September 1963.', '16 September 1963: Malaysia diisytiharkan serentak di Kuala Lumpur (Stadium Merdeka), Kuching, Kota Kinabalu dan City Hall Singapura. Jalur Gemilang dikibarkan. Semuanya bermula dengan mendengar.', 'Cemerlang! Urutan garis masa sejarah pembentukan negara telah berjaya anda susun dengan sempurna.'),
(NULL, 'e1_n2_s1', 'hint', 'Donald Stephens dan Tun Temenggung Jugah mengadakan perbincangan susulan pengumuman Tunku Abdul Rahman di Hotel Adelphi Singapura pada 27 Mei 1961. Di samping itu, sejarah cadangan awal Lord Brassey (1887) dan Malcolm MacDonald (1951) turut dikaji.', NULL, NULL),
(7, NULL, 'hint', 'Fikirkan faedah kemerdekaan pantas, pertahanan daripada komunis, dan pembangunan sosioekonomi.', 'Pengumuman Tunku (27 Mei 1961) membuka peluang kepada Borneo: kemerdekaan lebih awal, perlindungan daripada komunis dan ekonomi yang maju. Tetapi aku mendengar rakyat dahulu sebelum menjawab.', 'Syabas! Keputusan anda mencerminkan wawasan kepimpinan Borneo demi masa depan rakyat.'),
(NULL, 'e1_n2_s2', 'hint', 'Donald Stephens mempengerusikan Jawatankuasa Setia Kawan Malaysia (JSKM) pada 23 Julai 1961, manakala Suruhanjaya Cobbold tiba pada 17 Januari 1962 mengumpul pandangan rakyat bersama wakil Tanah Melayu seperti Ghazali Shafie dan Wong Pow Nee.', NULL, NULL),
(8, NULL, 'hint', 'Donald Stephens mempengerusikan JSKM manakala Laporan Cobbold mengesahkan sokongan 2/3 rakyat.', 'JSKM (23 Julai 1961) kami gunakan untuk menerangkan Malaysia. Cobbold (17 Januari 1962; Ghazali dan Wong Pow Nee antara ahlinya) mendengar rakyat. Laporan 21 Jun 1962: dua pertiga menyokong.', 'Padanan tepat! Usaha gigih ini berjaya menyatukan pandangan pelbagai etnik di Borneo.'),
(NULL, 'e1_n2_s3', 'hint', 'Dalam mesyuarat JAK yang dipengerusikan Lord Lansdowne dan Tun Abdul Razak pada 30 Ogos 1962, Donald Stephens dan pemimpin Borneo memperjuangkan Hak 20 Perkara Sabah serta tuntutan Sarawak.', NULL, NULL),
(9, NULL, 'hint', 'Hak keistimewaan merangkumi kawalan imigresen, agama, dan pentadbiran tempatan Borneo.', 'Di JAK (30 Ogos 1962, Lord Lansdowne dan Tun Razak) aku membawa Hak 20 Perkara Sabah; Sarawak membawa 18 Perkara. Imigresen, agama, bahasa dan perkhidmatan awam dilindungi dalam Perlembagaan.', 'Syabas! Perjuangan gigih anda berjaya mendaulat dan melindungi hak keistimewaan rakyat Borneo.'),
(NULL, 'e1_n2_s4', 'hint', 'Pemimpin Borneo menghadapi bantahan dalaman parti SUPP di Sarawak yang mahukan kemerdekaan berasingan, serta pencerobohan tentera Indonesia semasa Konfrontasi (20 Jan 1963) dan tuntutan Filipina ke atas Sabah.', NULL, NULL),
(10, NULL, 'hint', 'Cari risalah bantahan SUPP, laporan serangan Konfrontasi Indonesia, dan surat tuntutan Filipina.', 'Kami dicabar SUPP, Konfrontasi (20 Januari 1963) dan tuntutan Filipina. Hak yang sudah ditulis melalui JAK ialah jawapan terbaik kepada kebimbangan rakyat.', 'Cemerlang! Pengesanan bukti ancaman ini memperkukuh pertahanan dan perpaduan rakyat Borneo.'),
(NULL, 'e1_n2_s5', 'hint', 'Perjanjian Malaysia ditandatangani di Marlborough House London pada 9 Julai 1963. Seterusnya, Misi PBB (UNMM) pimpinan Laurence Michelmore tiba pada 12 Ogos 1963 untuk membuat penilaian rasmi.', NULL, NULL),
(11, NULL, 'hint', 'Siasatan UNMM PBB mengesahkan semula bahawa rakyat Borneo menyokong gabungan Malaysia.', 'Selepas perjanjian (9 Julai 1963), UNMM (12 Ogos 1963, Michelmore) bertanya kepada rakyat Borneo. Laporan 14 September 1963 mengesahkan sokongan bebas; 31 Ogos ditangguh ke 16 September.', 'Syabas! Pengesahan PBB ini membuktikan keabsahan perjuangan rakyat Borneo di arena antarabangsa.'),
(NULL, 'e1_n2_s6', 'hint', 'Donald Stephens membacakan Pemasyhuran Malaysia di Kota Kinabalu bersama Tun Datu Mustapha, manakala Stephen Kalong Ningkan membacakannya di Kuching bersama Tun Temenggung Jugah pada 16 September 1963.', NULL, NULL),
(12, NULL, 'hint', 'Urutan bermula dari Cadangan 1961, Penerangan JSKM, Tinjauan Cobbold 1962, Perjanjian London Julai 1963, dan Pemasyhuran 16 September 1963.', '16 September 1963: aku membaca Pemasyhuran di Kota Kinabalu, Stephen Kalong Ningkan di Kuching, Tunku di Stadium Merdeka dan City Hall Singapura. Empat tempat, satu hari, satu negara.', 'Cemerlang! Urutan sejarah pembentukan negara telah berjaya anda susun dengan tepat.'),
(NULL, 'e1_n3_s1', 'hint', 'Tun Ghazali Shafie menganalisis geopolitik Asia Tenggara susulan pengumuman Tunku Abdul Rahman di Hotel Adelphi Singapura pada 27 Mei 1961. Idea Lord Brassey (1887), Ibrahim Yaakob (1938), dan Malcolm MacDonald (1951) turut dijadikan rujukan.', NULL, NULL),
(13, NULL, 'hint', 'Penggabungan wilayah memperkukuh benteng pertahanan daripada resapan anasir komunis.', 'Empat sebab menyokong Malaysia: membendung komunis di Singapura dan Sarawak, mengimbangi kaum, mempercepat kemerdekaan dan memajukan ekonomi. Keselamatan hanya satu daripadanya.', 'Tepat sekali! Analisis strategik anda menjadi asas pertahanan dan diplomasi negara.'),
(NULL, 'e1_n3_s2', 'hint', 'Tun Ghazali Shafie dan Tan Sri Wong Pow Nee menganggotai Suruhanjaya Cobbold (17 Jan 1962). Laporan diserahkan pada 21 Jun 1962 selepas JSKM (23 Julai 1961) menerangkan Malaysia kepada rakyat.', NULL, NULL),
(14, NULL, 'hint', 'JSKM menerangkan, Cobbold mendengar, dan laporan 21 Jun 1962 mengesahkan sokongan dua pertiga.', 'JSKM (23 Julai 1961) menerangkan Malaysia. Cobbold (17 Januari 1962; aku dan Wong Pow Nee) mendengar rakyat. Laporan 21 Jun 1962: dua pertiga menyokong. Keraguan dijawab oleh JAK.', 'Cemerlang! Proses diplomasi dan perundangan berjaya disusun dengan teratur dan sah.'),
(NULL, 'e1_n3_s3', 'hint', 'Jawatankuasa Antara Kerajaan (JAK) bersidang pada 30 Ogos 1962 di bawah Lord Lansdowne dan Tun Abdul Razak. Hak 20 Perkara Sabah dan 18 Perkara Sarawak ditulis dalam Perlembagaan.', NULL, NULL),
(15, NULL, 'hint', 'JAK dipengerusikan oleh Lord Lansdowne dan Tun Razak. Hak yang ditulis dalam Perlembagaan menjadi undang-undang.', 'JAK (30 Ogos 1962, Lord Lansdowne dan Tun Razak) menulis Hak 20 Perkara Sabah dan 18 Perkara Sarawak ke dalam Perlembagaan. Aku memastikan ia bertulis, bukan janji lisan.', 'Tepat sekali! Hak Borneo kini tertulis dalam Perlembagaan, bukan sekadar janji.'),
(NULL, 'e1_n3_s4', 'hint', 'Tun Ghazali Shafie meneliti maklumat bantahan parti SUPP di Sarawak, pengisytiharan Konfrontasi Indonesia (Ganyang Malaysia) pada 20 Januari 1963, serta tuntutan Filipina ke atas Sabah.', NULL, NULL),
(16, NULL, 'hint', 'Cari bukti bantahan SUPP Sarawak, dokumen Konfrontasi Indonesia, dan tuntutan Filipina.', 'Tiga ancaman tiba serentak: bantahan SUPP, Konfrontasi (20 Januari 1963) dan tuntutan Filipina. Konfrontasi ancaman keselamatan sebenar, dua lagi dijawab dengan diplomasi.', 'Bukti ancaman berjaya dikesan! Data keselamatan ini digunakan untuk merangka jawapan diplomasi antarabangsa.'),
(NULL, 'e1_n3_s5', 'hint', 'Selepas Perjanjian Malaysia ditandatangani pada 9 Julai 1963 di Marlborough House London, Misi PBB (UNMM) ditubuhkan pada 12 Ogos 1963 di bawah Laurence Michelmore untuk membuat tinjauan semula.', NULL, NULL),
(17, NULL, 'hint', 'Laporan UNMM mengesahkan semula sokongan majoriti rakyat Borneo terhadap pembentukan Malaysia.', 'UNMM (12 Ogos 1963) mesti bebas bertemu sesiapa tanpa kita campur tangan. Laporan 14 September 1963 dipercayai kerana kita tidak menyentuhnya. Tarikh 31 Ogos ditangguh ke 16 September.', 'Syabas! Pengesahan PBB mematahkan tuduhan luar dan membuktikan ketelusan Malaysia kepada dunia.'),
(NULL, 'e1_n3_s6', 'hint', 'Tun Ghazali Shafie memantau kawalan keselamatan semasa Tunku Abdul Rahman membaca Teks Pemasyhuran Malaysia pada 16 September 1963 secara serentak di Kuala Lumpur, Kuching, Kota Kinabalu, dan Singapura.', NULL, NULL),
(18, NULL, 'hint', 'Urutan bermula dari Cadangan 1961, Penerangan JSKM, Tinjauan Cobbold 1962, Perjanjian London Julai 1963, dan Pemasyhuran 16 September 1963.', '16 September 1963: Pemasyhuran serentak di Stadium Merdeka (Kuala Lumpur), Kuching, Kota Kinabalu dan City Hall Singapura. Kerja keselamatan jarang dipuji, tetapi tanpanya majlis itu tidak berlangsung.', 'Cemerlang! Urutan peristiwa sejarah pembentukan negara telah berjaya anda susun dengan tepat.');
INSERT INTO DialogueLine (npcID, narrativeID, sceneID, dialogueLine, sequenceOrder) VALUES
(1, 1, NULL, 'Tugasku sebagai Perdana Menteri ialah meyakinkan lima wilayah bersatu tanpa paksaan: mendengar Borneo, menandatangani perjanjian dan mengisytiharkan Malaysia. Jika aku gagal mendengar, tiada Malaysia, dan rakyat Borneo terus menunggu kemerdekaan, {nama}.', 1),
(1, 1, NULL, 'Daripada perjalanan itu aku belajar bahawa perpaduan tidak dipaksa. Ia dibina dengan mendengar suara setiap pihak.', 2),
(1, 1, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, Perdana Menteri Persekutuan Tanah Melayu. Setiap keputusan yang kau ambil akan menentukan nasib lima wilayah. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(10, 1, 'e1_n1_s1', 'Tunku, dewan sudah penuh. Sekali kau sebut perkataan ''Malaysia'', semua mata akan memandang kau.', 1),
(4, 1, 'e1_n1_s1', 'Aku sokong gagasan ini, Tunku. Tetapi wartawan akan bertanya mengapa. Mereka mahu alasan, bukan slogan.', 2),
(10, 1, 'e1_n1_s1', 'Kita sudah bincangkan semalam: ada empat sebab. Kalau wartawan bertanya sekarang, Tunku, apa jawapan kau?', 3),
(4, 1, 'e1_n1_s1', 'Dengan jawapan itu kau menjawab soalan wartawan dan soalan rakyat. Tarikhnya 27 Mei 1961. Ingat tarikh ini.', 4),
(NULL, 1, 'e1_n1_s1', 'Aku tahu. Selepas ini setiap negeri akan bertanya, ''Apa untung kami?'' Kita mesti bersedia.', 5),
(10, 1, 'e1_n1_s1', 'Dan itu bermula di Borneo, Tunku. Kau perlu mendengar mereka, bukan hanya bercakap kepada mereka.', 6),
(10, 1, 'e1_n1_s1', 'Idea ini bukan baharu, Tunku: Lord Brassey 1887, Ibrahim Yaakob 1938, Malcolm MacDonald 1951. Kau sendiri pernah menyebutnya pada 1955.', 7),
(3, 1, 'e1_n1_s2', 'Tunku, JSKM ditubuhkan 23 Julai 1961. Setiap kampung bertanya sama ada Sabah dilayan sebagai rakan atau sekadar tambahan.', 1),
(10, 1, 'e1_n1_s2', 'Suruhanjaya Cobbold bermula 17 Januari 1962. Kami turun ke kampung-kampung sendiri. Kalau rakyat rasa dipaksa, laporan ini tidak bernilai.', 2),
(3, 1, 'e1_n1_s2', 'Seorang penduduk bertanya melalui aku, Tunku: ''Adakah kami dipaksa menyertai Malaysia?'' Apa jawapan kau?', 3),
(10, 1, 'e1_n1_s2', 'Laporan siap 21 Jun 1962. Dua pertiga menyokong, tetapi sokongan itu ada syaratnya.', 4),
(NULL, 1, 'e1_n1_s2', 'Syarat itu akan datang ke meja kita. Kita mesti bersedia menjawabnya satu demi satu.', 5),
(5, 1, 'e1_n1_s3', 'Tunku, JAK bersidang hari ini. Lord Lansdowne di sebelah sana, aku di sebelah sini. Setiap perenggan akan dibaca berkali-kali.', 1),
(2, 1, 'e1_n1_s3', 'Tunku, adat kami bukan hiasan. Tulis ia dalam perlembagaan, bukan dalam janji lisan sahaja.', 2),
(3, 1, 'e1_n1_s3', 'Tunku, ini tuntutan kami: Hak 20 Perkara untuk Sabah dan hak adat Sarawak. Bagaimana kau memastikan ia tidak dilupakan?', 3),
(5, 1, 'e1_n1_s3', 'Kita tulis satu demi satu. Tetapi cepat, Tunku, masa tidak menunggu kita.', 4),
(NULL, 1, 'e1_n1_s3', 'Kita tidak akan tergesa-gesa dalam perkara yang menentukan hak orang lain. Mari mulakan perenggan pertama.', 5),
(2, 1, 'e1_n1_s3', 'Sabah membawa 20 Perkara dan Sarawak 18 Perkara, Tunku. Lord Lansdowne dan Tun Razak mengerusikan JAK. Semuanya mesti ditulis.', 6),
(7, 1, 'e1_n1_s4', 'Tunku, kami tidak mahu Sarawak diserap tanpa suara sendiri. Merdeka dahulu, baru kita bincang gabungan. Itu pendirian SUPP.', 1),
(5, 1, 'e1_n1_s4', 'Indonesia sudah mengisytiharkan Konfrontasi pada 20 Januari 1963: ''Ganyang Malaysia''. Ini bukan lagi perbincangan dalam bilik, Tunku.', 2),
(10, 1, 'e1_n1_s4', 'Filipina pula menuntut Sabah. Tunku, kita boleh minta PBB bertanya kepada rakyat Borneo sendiri, supaya bukan kita yang menjawab bagi pihak mereka. Apa pendapat kau?', 3),
(5, 1, 'e1_n1_s4', 'Kita tidak boleh menjawab ketiga-tiganya sekali gus. Pilih dahulu yang paling mendesak, kemudian rujuk PBB.', 4),
(NULL, 1, 'e1_n1_s4', 'Kumpulkan semua dokumen di atas meja. Aku mahu melihat buktinya sebelum membuat keputusan.', 5),
(5, 1, 'e1_n1_s5', 'Tunku, Marlborough House, 9 Julai 1963. Pen sudah di tangan kau. Tetapi Indonesia dan Filipina belum puas hati, jadi tandatangan ini belum menutup cerita.', 1),
(10, 1, 'e1_n1_s5', 'PBB menghantar misi UNMM pada 12 Ogos 1963. Laurence Michelmore akan bertanya kepada rakyat Borneo, bukan kepada kita.', 2),
(3, 1, 'e1_n1_s5', 'Tunku, kalau Michelmore bertanya kepada kau, siapa yang patut menentukan sama ada Sabah dan Sarawak mahu menyertai Malaysia?', 3),
(3, 1, 'e1_n1_s5', 'Rakyat kami akan menjawab dengan jujur, Tunku. Itu sebab aku tidak risau, cuma berdebar.', 4),
(NULL, 1, 'e1_n1_s5', 'Laporan itu akan tiba tidak lama lagi. Kita tunggu, dan kita terima apa sahaja jawapannya.', 5),
(10, 1, 'e1_n1_s5', 'Tarikh asal 31 Ogos 1963 ditangguhkan ke 16 September, Tunku, supaya PBB sempat bertanya kepada rakyat Borneo dahulu.', 6),
(5, 1, 'e1_n1_s6', 'Tunku, esok 16 September 1963. Kau sudah membaca teks ini puluhan kali.', 1),
(NULL, 1, 'e1_n1_s6', 'Tetapi bila berdiri nanti, aku mahu ia terasa seperti kali pertama.', 2),
(10, 1, 'e1_n1_s6', 'Laporan UNMM tiba 14 September, dan ia menyokong kita. Selepas ini tiada lagi ''kalau''. Hanya ''bila''.', 3),
(6, 1, 'e1_n1_s6', 'Tunku, Sarawak mahu dilihat sebagai rakan, bukan pengikut. Pemasyhuran dibaca serentak di Kuala Lumpur, Kuching, Kota Kinabalu dan Singapura. Mengapa ia mesti serentak?', 4),
(NULL, 1, 'e1_n1_s6', 'Kita bina ini bersama. Pastikan setiap suara didengar, kerana negara ini bermula daripada suara-suara itu.', 5),
(5, 1, 'e1_n1_s6', 'Di Singapura, Pemasyhuran dibaca di City Hall, Tunku. Jalur Gemilang dikibarkan sebagai lambang negara baharu, di Stadium Merdeka tempat kau melaungkan Merdeka pada 31 Ogos 1957.', 6),
(3, 2, NULL, 'Tugasku ialah membawa suara rakyat Borneo ke meja perundingan dan memastikan hak kami ditulis dalam Perlembagaan. Jika suara itu tidak sampai, Sabah dan Sarawak hanya menjadi tambahan, bukan rakan, {nama}.', 1),
(3, 2, NULL, 'Aku belajar bahawa penyertaan yang adil hanya wujud apabila suara kecil diberi tempat di meja perundingan.', 2),
(3, 2, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, Pengerusi JSKM dari Sabah. Rakyat Borneo menunggu jawapan kau: adakah mereka rakan, atau sekadar tambahan? Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(9, 2, 'e1_n2_s1', 'Donald, dia sudah umumkan di Adelphi pada 27 Mei 1961. Sekarang bola ada pada kita. Terima atau tolak, kita mesti tahu apa yang kita mahu.', 1),
(2, 2, 'e1_n2_s1', 'Aku sudah tua, Donald, dan aku dengar cerita ini sejak zaman Brassey lagi. Orang putih bercakap, tanah kami tidak ditanya.', 2),
(2, 2, 'e1_n2_s1', 'Aku bimbang kami hanya diberitahu, bukan ditanya. Kalau kau di tempat kami, apa yang patut dibuat dahulu sebelum menjawab Tunku?', 3),
(NULL, 2, 'e1_n2_s1', 'Kali ini lain, Tun. Kemerdekaan lebih awal, perlindungan daripada komunis, ekonomi yang bergerak. Tetapi hanya jika kita bangun dan bersuara.', 4),
(9, 2, 'e1_n2_s1', 'Maka bersuaralah dengan jelas, Donald. Seluruh Sabah memerhati.', 5),
(9, 2, 'e1_n2_s1', 'Idea ini pun bukan baharu, Donald: Lord Brassey 1887, Ibrahim Yaakob 1938, Malcolm MacDonald 1951, dan Tunku sendiri pada 1955. Cuma kali ini ia diumumkan terang-terangan di Adelphi.', 6),
(2, 2, 'e1_n2_s2', 'Donald, JSKM bermula 23 Julai 1961. Setiap kampung mahu tahu apa itu Malaysia, dan kau tidak boleh menjawab dengan ''tidak pasti''.', 1),
(9, 2, 'e1_n2_s2', 'Rakyat bertanya tentang agama dan tanah. Jangan jawab dengan janji kosong, Donald. Mereka ingat setiap perkataan.', 2),
(2, 2, 'e1_n2_s2', 'Cobbold akan tiba pada 17 Januari 1962 untuk mendengar rakyat. Seorang penduduk bertanya kepada kau, ''Adakah suara kami benar-benar dicatat?'' Apa jawapan kau?', 3),
(2, 2, 'e1_n2_s2', 'Laporan 21 Jun 1962 menunjukkan majoriti menyokong. Tetapi sokongan ini datang dengan harapan, dan harapan mesti ditunaikan.', 4),
(NULL, 2, 'e1_n2_s2', 'Aku faham, Tun. Aku akan bawa harapan itu ke meja JAK.', 5),
(5, 2, 'e1_n2_s3', 'Donald, Hak 20 Perkara. Bawa senarai ini ke meja. Kalau mahu Borneo menjadi sebahagian Malaysia, inilah asasnya.', 1),
(2, 2, 'e1_n2_s3', 'Sarawak juga ada tuntutan. Imigresen, adat, pentadbiran tempatan. Jangan biarkan kami hanya disebut dalam lampiran.', 2),
(5, 2, 'e1_n2_s3', 'JAK bersidang hari ini dengan Lord Lansdowne. Apa yang dipersetujui di sini akan menjadi Perlembagaan. Kau wakil Borneo di meja ini, Donald: apa yang kau minta?', 3),
(NULL, 2, 'e1_n2_s3', '30 Ogos 1962. Ingat tarikh ini. Hari kita menulis hak kita sendiri.', 4),
(5, 2, 'e1_n2_s3', 'Sarawak pula membawa 18 Perkara, Donald. Dua senarai, satu Perlembagaan.', 5),
(6, 2, 'e1_n2_s4', 'Donald, SUPP bising di dewan. Mereka mahu Sarawak merdeka berasingan. Kita mesti jawab dengan hak yang sudah ditulis dalam Perlembagaan melalui JAK, bukan mengabaikannya.', 1),
(9, 2, 'e1_n2_s4', 'Di luar, tentera Indonesia melintas sempadan. Konfrontasi bermula 20 Januari 1963. Ini bukan sekadar pertikaian politik.', 2),
(9, 2, 'e1_n2_s4', 'Filipina pula menuntut Sabah. Mereka yang ragu bimbang suara kita hilang. Donald, bagaimana kau meyakinkan mereka?', 3),
(NULL, 2, 'e1_n2_s4', 'Kita tidak boleh biarkan sesiapa menentukan masa depan kita tanpa bertanya kita dahulu. Mari kumpulkan buktinya.', 4),
(9, 2, 'e1_n2_s4', 'Slogan mereka ialah ''Ganyang Malaysia'', Donald. Kita mesti tahu mana ancaman sebenar dan mana yang boleh dijawab dengan hak yang tertulis.', 5),
(6, 2, 'e1_n2_s5', 'Donald, Marlborough House, 9 Julai 1963. Kau menandatangani Perjanjian. Tanganku sedikit bergetar. Ini bukan dokumen biasa.', 1),
(6, 2, 'e1_n2_s5', 'Indonesia dan Filipina masih membantah. Jadi PBB menghantar UNMM pada 12 Ogos 1963. Michelmore mahu mendengar sendiri daripada rakyat kita.', 2),
(2, 2, 'e1_n2_s5', 'Biar mereka datang ke rumah panjang. Tetapi katakan, Donald: kalau pegawai PBB bertanya kepada kau, ''Adakah anda menyokong Malaysia?'', bagaimana kau menjawab?', 3),
(6, 2, 'e1_n2_s5', 'Laporan UNMM 14 September 1963 menyokong kita. Tetapi semua orang di sini tahu, selepas ini barulah kerja sebenar bermula.', 4),
(6, 2, 'e1_n2_s5', 'Tarikh asal 31 Ogos 1963 ditangguhkan ke 16 September, Donald, supaya PBB sempat bertanya kepada rakyat dahulu.', 5),
(9, 2, 'e1_n2_s6', 'Donald, 16 September 1963. Kau akan membacanya di Kota Kinabalu. Aku tahu kau sudah membaca seratus kali, tetapi hari ini lain.', 1),
(NULL, 2, 'e1_n2_s6', 'Hari ini lain, Tun. Seluruh Sabah di hadapan aku.', 2),
(9, 2, 'e1_n2_s6', 'Tenang. Seluruh Sabah di belakang kau. Baca perlahan, supaya setiap orang dengar.', 3),
(6, 2, 'e1_n2_s6', 'Di Kuching, aku membacanya bersama Tun Jugah. Donald, kalau seseorang bertanya siapa yang membacakan Pemasyhuran di Sabah dan di Sarawak, apa kau jawab?', 4),
(2, 2, 'e1_n2_s6', 'Hari ini bukan akhir perjuangan. Ia permulaan tanggungjawab kita bersama.', 5),
(9, 2, 'e1_n2_s6', 'Di Kuala Lumpur, Tunku membaca Pemasyhuran di Stadium Merdeka, tempat Merdeka dilaungkan pada 31 Ogos 1957. Di Singapura, di City Hall. Jalur Gemilang dikibarkan sebagai lambang negara baharu.', 6),
(10, 3, NULL, 'Tugasku ialah menjaga keselamatan dan diplomasi di belakang tabir: menghadapi Konfrontasi, tuntutan Filipina dan memastikan PBB mengesahkan pilihan rakyat. Jika satu kesilapan berlaku, seluruh rancangan runtuh, {nama}.', 1),
(10, 3, NULL, 'Aku belajar bahawa keselamatan sebenar dibina dengan diplomasi, kejujuran dan pengesahan yang bebas.', 2),
(10, 3, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, diplomat dan perunding keselamatan negara. Kau bekerja di belakang tabir, dan satu kesilapan boleh meruntuhkan segalanya. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1, 3, 'e1_n3_s1', 'Ghazali, aku sudah bercakap di Adelphi. Sekarang aku perlukan kau membaca keadaan rantau dengan jelas.', 1),
(1, 3, 'e1_n3_s1', 'Singapura bergolak, Sarawak pun ada tanda-tandanya. Tetapi bukan komunis sahaja: ada keseimbangan kaum, kemerdekaan lebih awal untuk Borneo, dan ekonomi yang maju. Empat sebab, saling berkait.', 2),
(4, 3, 'e1_n3_s1', 'Aku sokong penggabungan, Ghazali, tetapi keselamatan sahaja tidak cukup. Seorang pelajar bertanya kepada kau, ''Mengapa Malaysia dicadangkan?'' Apa jawapan kau?', 3),
(NULL, 3, 'e1_n3_s1', 'Setiap sebab menjawab satu kebimbangan rakyat. Catat tarikhnya: 27 Mei 1961.', 4),
(4, 3, 'e1_n3_s1', 'Idea ini bukan baharu, Ghazali: Lord Brassey 1887, Ibrahim Yaakob 1938, Malcolm MacDonald 1951, Tunku 1955. Hotel Adelphi hanya menyatukannya.', 5),
(1, 3, 'e1_n3_s2', 'Ghazali, JSKM bermula 23 Julai 1961 di bawah Donald Stephens untuk menerangkan Malaysia. Cobbold bermula 17 Januari 1962, dan kau bersama Wong Pow Nee dalam suruhanjaya itu.', 1),
(5, 3, 'e1_n3_s2', 'Apa yang rakyat Borneo katakan kepada kau, Ghazali? Aku mahu dengar sebenar-benarnya, bukan versi yang menyenangkan.', 2),
(NULL, 3, 'e1_n3_s2', 'Laporan siap 21 Jun 1962: dua pertiga menyokong. Tetapi ada juga yang ragu, dan keraguan itu mesti dijawab, bukan disenyapkan.', 3),
(5, 3, 'e1_n3_s2', 'Betul. Jadi, Ghazali, apa yang patut kita lakukan dengan keraguan mereka yang belum menyokong?', 4),
(1, 3, 'e1_n3_s2', 'Selepas ini JAK akan menulis jawapannya, bukan sekadar janji.', 5),
(5, 3, 'e1_n3_s3', 'Ghazali, JAK bersidang 30 Ogos 1962. Lord Lansdowne dan aku mengerusikannya. Setiap perenggan akan disemak berkali-kali.', 1),
(3, 3, 'e1_n3_s3', 'Sabah menuntut Hak 20 Perkara, Ghazali, dan Sarawak membawa 18 Perkara. Kami mahu semuanya ditulis, bukan dijanjikan.', 2),
(2, 3, 'e1_n3_s3', 'Adat kami bukan hiasan, Ghazali. Jika ia tidak tertulis, ia hilang bersama orang yang berjanji. Bagaimana kau memastikan ia dijaga?', 3),
(5, 3, 'e1_n3_s3', 'Cepat, Ghazali, masa tidak menunggu kita. Tetapi perenggan demi perenggan, tanpa tergesa-gesa.', 4),
(NULL, 3, 'e1_n3_s3', 'Hak yang ditulis menjadi undang-undang. Kita tidak akan tergesa-gesa dalam perkara yang menentukan hak orang lain.', 5),
(5, 3, 'e1_n3_s4', 'Ghazali, SUPP mahu merdeka berasingan. Indonesia mengisytiharkan Konfrontasi 20 Januari 1963. Filipina menuntut Sabah. Tiga ancaman, satu meja.', 1),
(1, 3, 'e1_n3_s4', 'Mana satu yang paling mendesak, Ghazali? Aku perlu tahu sebelum membuat keputusan.', 2),
(5, 3, 'e1_n3_s4', 'Konfrontasi ialah ancaman keselamatan: tentera melintas sempadan. SUPP dan Filipina boleh dijawab dengan perundingan dan diplomasi. Menurut kau, yang mana kita tangani dahulu?', 3),
(1, 3, 'e1_n3_s4', 'Susun mengikut keutamaan. Aku tidak mahu satu masalah kecil menjadi sebab seluruh rancangan terhenti.', 4),
(5, 3, 'e1_n3_s4', 'Slogan mereka ''Ganyang Malaysia'', Ghazali. Jangan silap menilai: ia ancaman sebenar.', 5),
(1, 3, 'e1_n3_s5', 'Ghazali, Marlborough House, 9 Julai 1963. Perjanjian sudah ditandatangani. Tetapi aku masih gelisah, kerana bantahan tidak berhenti begitu sahaja.', 1),
(5, 3, 'e1_n3_s5', 'UNMM bermula 12 Ogos 1963, diketuai Laurence Michelmore. Prinsip PBB jelas: laporan hanya dipercayai jika pegawainya bebas bertemu sesiapa tanpa kita campur tangan.', 2),
(1, 3, 'e1_n3_s5', 'Kau penasihatku, Ghazali. Patutkah kita menemani pegawai UNMM ke mana-mana mereka pergi, atau biarkan mereka bertemu sesiapa sahaja sendiri?', 3),
(NULL, 3, 'e1_n3_s5', 'Biar mereka sendiri mendengar rakyat. Laporan 14 September akan lebih berharga jika kita tidak mencampurinya.', 4),
(5, 3, 'e1_n3_s5', 'Tarikh asal 31 Ogos 1963 ditangguhkan ke 16 September, Ghazali, supaya PBB sempat bertanya dahulu.', 5),
(1, 3, 'e1_n3_s6', 'Ghazali, 16 September 1963. Empat bandar serentak: Kuala Lumpur, Kuching, Kota Kinabalu, Singapura. Satu kesilapan masa, dan semua orang akan nampak.', 1),
(5, 3, 'e1_n3_s6', 'Kawalan keselamatan sudah disusun. Tetapi hari ini bukan hari untuk menyangka semuanya selamat.', 2),
(1, 3, 'e1_n3_s6', 'Aku bakal membaca Pemasyhuran. Kau menjaga keselamatan majlis. Apa tugas utama kau hari ini, Ghazali: menjadi pusat perhatian, atau memastikan majlis berjalan tanpa gangguan?', 3),
(NULL, 3, 'e1_n3_s6', 'Diplomasi, peninjauan dan keselamatan. Itulah tiga tiang, dan hari ini ketiga-tiganya berdiri.', 4),
(5, 3, 'e1_n3_s6', 'Di Stadium Merdeka, tempat Merdeka dilaungkan pada 31 Ogos 1957, Tunku membaca Pemasyhuran. Di Singapura, di City Hall. Jalur Gemilang dikibarkan sebagai lambang negara baharu.', 5);
INSERT INTO QuestionBank (bankID, eraID) VALUES (1, 1)
INSERT INTO Question (questionID, bankID, questionText, option_a, option_b, option_c, option_d, correctAnswer, hint, explanation) VALUES
(101, 1, 'Siapakah tokoh British yang mula-mula mencadangkan penggabungan wilayah Borneo dan Negeri-Negeri Selat pada tahun 1887?', 'Sir Frank Swettenham', 'Sir Hugh Low', 'Lord Brassey', 'Sir Hugh Clifford', 'C', 'Idea ini timbul hampir 75 tahun sebelum Tunku membuat pengumuman rasmi.', 'Lord Brassey mencadangkan penggabungan wilayah Borneo dan Negeri-Negeri Selat pada 1887. Ini antara idea terawal ke arah gabungan wilayah.'),
(102, 1, 'Apakah konsep penggabungan wilayah yang dicadangkan oleh Ibrahim Haji Yaakob dan Harun Aminurrashid pada tahun 1938?', 'Melayu Raya, gabungan Tanah Melayu dan Kepulauan Indonesia', 'Nusantara Raya, gabungan Indonesia dan Borneo Utara sahaja', 'Malaya Raya, gabungan Tanah Melayu dan Singapura sahaja', 'Asia Raya, gabungan Tanah Melayu dan Kepulauan Filipina', 'A', 'Konsep ini merangkumi Tanah Melayu dan Kepulauan Indonesia.', 'Konsep Melayu Raya menggabungkan Tanah Melayu bersama Kepulauan Indonesia. Ia dikemukakan pada 1938 oleh Ibrahim Haji Yaakob dan Harun Aminurrashid.'),
(103, 1, 'Siapakah Gabenor Jeneral British yang menganjurkan perbincangan awal mengenai penggabungan wilayah pada tahun 1951?', 'Sir Gerald Templer', 'Malcolm MacDonald', 'Sir Henry Gurney', 'Lord Mountbatten', 'B', 'Beliau mewakili British di Asia Tenggara dan menganjurkan perbincangan pada 1951.', 'Malcolm MacDonald menganjurkan perbincangan awal tentang penggabungan wilayah pada tahun 1951.'),
(104, 1, 'Bilakah dan di manakah Tunku Abdul Rahman Putra Al-Haj pertama kali menyatakan gagasan penggabungan Tanah Melayu, Singapura, Sarawak, Sabah dan Brunei?', 'Pada tahun 1953 semasa persidangan wartawan asing di Singapura', 'Pada tahun 1951 semasa lawatan Malcolm MacDonald di Kuching', 'Pada tahun 1957 semasa upacara Kemerdekaan di Stadium Merdeka', 'Pada tahun 1955 semasa Dewan Perhimpunan di Kuala Lumpur', 'D', 'Gagasan ini dinyatakan sebelum Tanah Melayu merdeka.', 'Tunku mula menyatakan gagasan penggabungan lima wilayah itu pada tahun 1955 semasa Dewan Perhimpunan di Kuala Lumpur.'),
(105, 1, 'Di manakah dan bilakah Tunku Abdul Rahman mengumumkan cadangan Pembentukan Malaysia kepada media antarabangsa?', 'Hotel Adelphi, Singapura pada 27 Mei 1963', 'Hotel Raffles, Singapura pada 27 Mei 1961', 'Hotel Adelphi, Singapura pada 27 Mei 1961', 'Stadium Merdeka, Kuala Lumpur pada 27 Mei 1961', 'C', 'Pengumuman dibuat semasa majlis makan tengah hari Persatuan Wartawan Luar Negeri Asia Tenggara.', 'Pada 27 Mei 1961, Tunku mengumumkan cadangan Pembentukan Malaysia di Hotel Adelphi, Singapura, semasa majlis makan tengah hari Persatuan Wartawan Luar Negeri Asia Tenggara.'),
(106, 1, 'Apakah faktor keselamatan utama yang mendorong cadangan Pembentukan Malaysia pada tahun 1961?', 'Menghalang pengaruh ekonomi asing di Singapura dan Sarawak', 'Menamatkan pertikaian sempadan di Sabah dan Sarawak', 'Membendung penyebaran fahaman komunis di Thailand dan Kemboja', 'Membendung penyebaran fahaman komunis di Singapura dan Sarawak', 'D', 'Ancaman ini berkait dengan satu fahaman politik yang berkembang di Singapura dan Sarawak.', 'Penggabungan dilihat dapat membendung ancaman fahaman komunis di Singapura dan Sarawak.'),
(107, 1, 'Mengapakah penggabungan Singapura dan wilayah Borneo penting dari segi keseimbangan kaum?', 'Mengimbangi nisbah penduduk Bumiputera dan bukan Bumiputera', 'Mengimbangi nisbah penduduk bandar dan luar bandar sahaja', 'Menjadikan penduduk Bumiputera majoriti dua pertiga di Singapura', 'Menyamakan jumlah penduduk Singapura dengan Tanah Melayu', 'A', 'Fikirkan komposisi penduduk selepas Singapura yang ramai penduduk bukan Bumiputera bergabung.', 'Penyertaan wilayah Borneo yang ramai penduduk Bumiputera mengimbangi komposisi kaum apabila Singapura bergabung.'),
(108, 1, 'Bagaimanakah Pembentukan Malaysia memberi faedah politik kepada Sarawak, Sabah dan Singapura?', 'Menyerahkan hal ehwal luar kepada Pertubuhan PBB', 'Mengekalkan perlindungan British sehingga tahun 1970', 'Mempercepatkan kemerdekaan daripada pentadbiran British', 'Memindahkan pentadbiran wilayah itu kepada Brunei', 'C', 'Ketiga-tiga wilayah masih berada di bawah penjajah ketika itu.', 'Melalui Pembentukan Malaysia, Sarawak, Sabah dan Singapura memperoleh kemerdekaan daripada pentadbiran British dengan lebih cepat.'),
(109, 1, 'Apakah faedah sosioekonomi yang diperoleh melalui penggabungan negeri-negeri dalam Malaysia?', 'Taraf hidup meningkat dan pasaran ekonomi bersama dimajukan', 'Taraf hidup meningkat kerana semua cukai dihapuskan', 'Pelaburan asing meningkat kerana pasaran dibahagi mengikut negeri', 'Pasaran ekonomi dimajukan kerana perdagangan antara negeri dihentikan', 'A', 'Faedahnya berkaitan kehidupan rakyat dan ekonomi bersama.', 'Penggabungan membolehkan pasaran bersama dan penyatuan sumber kekayaan, lalu meningkatkan taraf hidup rakyat.'),
(110, 1, 'Siapakah Perdana Menteri Persekutuan Tanah Melayu yang digelar Arsitek Utama Pembentukan Malaysia?', 'Tun Dr. Ismail', 'Tun Tan Cheng Lock', 'Tun Abdul Razak bin Hussein', 'Tunku Abdul Rahman Putra Al-Haj', 'D', 'Beliau ialah Perdana Menteri pertama dan Bapa Kemerdekaan.', 'Tunku Abdul Rahman mencetuskan dan menggerakkan gagasan Pembentukan Malaysia, maka beliau digelar Arsitek Utamanya.'),
(111, 1, 'Bilakah Jawatankuasa Setia Kawan Malaysia (JSKM) ditubuhkan selepas pengumuman di Singapura?', '17 Januari 1962', '27 Mei 1961', '23 Julai 1961', '9 Julai 1963', 'C', 'Ia ditubuhkan kira-kira dua bulan selepas pengumuman Tunku.', 'JSKM ditubuhkan pada 23 Julai 1961, selepas pengumuman Tunku pada 27 Mei 1961.'),
(112, 1, 'Siapakah tokoh dari Sabah yang dilantik sebagai pengerusi Jawatankuasa Setia Kawan Malaysia (JSKM)?', 'Tun Temenggung Jugah anak Barieng', 'Donald Stephens (Tun Fuad Stephens)', 'Lee Kuan Yew', 'Tun Datu Mustapha bin Datu Harun', 'B', 'Beliau kemudian menjadi Ketua Menteri Sabah yang pertama.', 'Donald Stephens, yang kemudian dikenali sebagai Tun Fuad Stephens, mengetuai JSKM.'),
(113, 1, 'Apakah peranan utama Jawatankuasa Setia Kawan Malaysia (JSKM)?', 'Menyediakan saluran perbincangan dan mengumpul pandangan pemimpin Borneo', 'Menyediakan draf Perlembagaan untuk dibentangkan di London', 'Menjalankan pungutan suara rasmi di seluruh Sabah dan Sarawak', 'Menyediakan pasukan tentera bagi mempertahankan sempadan Borneo', 'A', 'Nama jawatankuasa ini membawa maksud kesetiakawanan dan perundingan.', 'JSKM menjadi saluran perbincangan untuk menerangkan gagasan Malaysia dan mengumpul pandangan pemimpin serta rakyat Borneo.'),
(114, 1, 'Berapa kali mesyuarat perundingan JSKM diadakan sebelum mengesyorkan penubuhan suruhanjaya peninjau, dan di mana?', 'Empat kali: Jesselton, Kuching, Brunei dan London', 'Empat kali: Jesselton, Kuching, Kuala Lumpur dan Singapura', 'Lima kali: Jesselton, Kuching, Singapura, London dan Brunei', 'Tiga kali: Jesselton, Kuching dan Kuala Lumpur', 'B', 'Mesyuarat diadakan di empat bandar utama.', 'JSKM bermesyuarat empat kali di Jesselton, Kuching, Kuala Lumpur dan Singapura sebelum mengesyorkan suruhanjaya peninjau.'),
(115, 1, 'Bilakah Suruhanjaya Cobbold ditubuhkan secara rasmi?', '17 Januari 1962', '14 September 1963', '21 Jun 1962', '30 Ogos 1962', 'A', 'Ia ditubuhkan pada awal tahun 1962.', 'Suruhanjaya Cobbold ditubuhkan oleh Kerajaan British dan Persekutuan Tanah Melayu pada 17 Januari 1962.'),
(116, 1, 'Apakah tugas utama Suruhanjaya Cobbold semasa melawat Sabah dan Sarawak antara Februari hingga April 1962?', 'Menyelesaikan tuntutan Filipina ke atas Sabah dan Sarawak', 'Menyediakan draf Perlembagaan untuk Sabah dan Sarawak', 'Meninjau pandangan rakyat Sabah dan Sarawak tentang Malaysia', 'Mengesahkan keputusan Perjanjian Malaysia di Borneo', 'C', 'Suruhanjaya ini menjelajah Borneo untuk mendengar suara rakyat.', 'Suruhanjaya Cobbold meninjau pandangan dan reaksi rakyat Sabah serta Sarawak terhadap cadangan Pembentukan Malaysia.'),
(117, 1, 'Siapakah dua tokoh tempatan dari Persekutuan Tanah Melayu yang menjadi anggota Suruhanjaya Cobbold?', 'Tun Abdul Razak dan Tun Dr. Ismail', 'Tun Tan Siew Sin dan Tun V.T. Sambanthan', 'Tun Muhammad Ghazali Shafie dan Tun Dr. Ismail', 'Tun Muhammad Ghazali Shafie dan Tan Sri Wong Pow Nee', 'D', 'Salah seorang daripadanya ialah Ketua Menteri Pulau Pinang.', 'Suruhanjaya Cobbold dianggotai Tun Muhammad Ghazali Shafie dan Tan Sri Wong Pow Nee bersama wakil British.'),
(118, 1, 'Berapakah nisbah penduduk Sabah dan Sarawak yang menyokong Pembentukan Malaysia menurut Suruhanjaya Cobbold?', 'Tiga perempat (3/4)', 'Dua pertiga (2/3)', 'Satu perempat (1/4)', 'Separuh (1/2)', 'B', 'Nisbah ini lebih daripada separuh tetapi kurang daripada tiga perempat.', 'Laporan Cobbold mendapati kira-kira dua pertiga penduduk Sabah dan Sarawak menyokong pembentukan Malaysia.'),
(119, 1, 'Bagaimanakah pandangan rakyat Sabah dan Sarawak dibahagikan dalam Laporan Suruhanjaya Cobbold?', 'Satu pertiga menyokong penuh, satu pertiga menentang, satu pertiga berkecuali', 'Dua pertiga menyokong penuh dan satu pertiga mahu merdeka dahulu', 'Separuh menyokong penuh, satu perempat bersyarat, satu perempat menentang', 'Satu pertiga menyokong penuh, satu pertiga bersyarat, satu pertiga mahu merdeka dahulu', 'D', 'Pandangan terbahagi kepada tiga kumpulan yang hampir sama besar.', 'Satu pertiga menyokong penuh, satu pertiga menyokong dengan syarat hak dipelihara dan satu pertiga mahukan kemerdekaan berasingan dahulu.'),
(120, 1, 'Bilakah Laporan Suruhanjaya Cobbold diserahkan kepada Kerajaan British dan Persekutuan Tanah Melayu?', '27 Mei 1961', '21 Jun 1962', '30 Ogos 1962', '17 Januari 1962', 'B', 'Laporan siap kira-kira lima bulan selepas suruhanjaya ditubuhkan.', 'Laporan Suruhanjaya Cobbold diserahkan secara rasmi pada 21 Jun 1962.'),
(121, 1, 'Bilakah Jawatankuasa Antara Kerajaan (JAK) ditubuhkan?', '12 Ogos 1963', '9 Julai 1963', '30 Ogos 1962', '21 Jun 1962', 'C', 'Ia ditubuhkan selepas Laporan Cobbold diserahkan.', 'JAK ditubuhkan pada 30 Ogos 1962 untuk menyusun butiran pembentukan Malaysia.'),
(122, 1, 'Siapakah dua tokoh yang memimpin dan mempengerusikan mesyuarat Jawatankuasa Antara Kerajaan (JAK)?', 'Lord Lansdowne dan Tun Abdul Razak bin Hussein', 'Lord Lansdowne dan Tunku Abdul Rahman Putra', 'Malcolm MacDonald dan Tun Abdul Razak bin Hussein', 'Lord Cobbold dan Tun Abdul Razak bin Hussein', 'A', 'Seorang mewakili British, seorang lagi ialah Timbalan Perdana Menteri Persekutuan Tanah Melayu.', 'Lord Lansdowne mewakili British dan Tun Abdul Razak mewakili Persekutuan Tanah Melayu dalam memimpin JAK.'),
(123, 1, 'Apakah tanggungjawab utama Jawatankuasa Antara Kerajaan (JAK)?', 'Merangka Perlembagaan dan melindungi hak Sabah dan Sarawak', 'Mengesahkan persetujuan rakyat di bawah pengawasan PBB', 'Merunding penyelesaian tuntutan Filipina ke atas Sabah', 'Meninjau pandangan rakyat dan melaporkannya kepada British', 'A', 'Jawatankuasa ini bekerja pada peringkat kerajaan, bukan meninjau rakyat.', 'JAK bertanggungjawab merangka Perlembagaan Malaysia dan peruntukan perlindungan hak istimewa Sabah serta Sarawak.'),
(124, 1, 'Apakah nama dokumen peruntukan khas yang dikemukakan pemimpin Sabah untuk dimasukkan ke dalam perlembagaan?', 'Tuntutan Hak 18 Perkara Sabah', 'Tuntutan Hak 14 Perkara Borneo', 'Tuntutan Hak 20 Perkara Sabah', 'Tuntutan Hak 20 Perkara Sarawak', 'C', 'Dokumen ini dikemukakan bagi melindungi hak istimewa Sabah.', 'Pemimpin Sabah mengemukakan Tuntutan Hak 20 Perkara Sabah supaya hak negeri itu terpelihara dalam perlembagaan.'),
(125, 1, 'Nyatakan dua perkara penting yang dilindungi dalam hak istimewa Sabah dan Sarawak melalui perlembagaan.', 'Kuasa kewangan dan agama', 'Kuasa imigresen dan agama', 'Kuasa luar negeri dan pendidikan', 'Kuasa pertahanan dan imigresen', 'B', 'Bidang ini kekal di bawah kawalan negeri, bukan Persekutuan.', 'Hak istimewa yang dilindungi merangkumi kuasa imigresen, agama, bahasa dan pentadbiran perkhidmatan awam tempatan.'),
(126, 1, 'Bilakah Perjanjian Malaysia ditandatangani secara rasmi di London?', '9 Julai 1963', '16 September 1963', '31 Ogos 1963', '14 September 1963', 'A', 'Ia berlaku beberapa bulan sebelum Pemasyhuran Malaysia.', 'Perjanjian Malaysia ditandatangani di London pada 9 Julai 1963.'),
(127, 1, 'Di manakah Perjanjian Malaysia 1963 ditandatangani?', 'Stadium Merdeka, Kuala Lumpur', 'Hotel Adelphi, Singapura', 'Marlborough House, London', 'Istana Buckingham, London', 'C', 'Tempat ini ialah sebuah rumah bersejarah di London.', 'Perjanjian Malaysia ditandatangani di Marlborough House, London.'),
(128, 1, 'Siapakah pihak yang menandatangani Perjanjian Malaysia pada 9 Julai 1963?', 'Wakil British, Tanah Melayu, Sabah, Sarawak dan Brunei', 'Wakil Tanah Melayu, Sabah, Sarawak, Singapura dan PBB', 'Wakil British, Tanah Melayu, Singapura dan Indonesia', 'Wakil British, Tanah Melayu, Sabah, Sarawak dan Singapura', 'D', 'Semua pihak yang akan membentuk Malaysia hadir bersama British.', 'Perjanjian itu ditandatangani oleh wakil British, Persekutuan Tanah Melayu, Sabah, Sarawak dan Singapura.'),
(129, 1, 'Apakah ikrar utama dalam Perjanjian Malaysia 1963?', 'Persetujuan perundangan bagi menubuhkan persekutuan Malaysia', 'Persetujuan perundangan bagi meneruskan pentadbiran British', 'Persetujuan perundangan bagi menggabungkan Singapura dengan Indonesia', 'Persetujuan perundangan bagi menubuhkan Persekutuan Borneo', 'A', 'Perjanjian ini menetapkan syarat penubuhan sebuah negara baharu.', 'Perjanjian Malaysia menetapkan persetujuan dan syarat perundangan bagi penubuhan persekutuan Malaysia yang berdaulat.'),
(130, 1, 'Siapakah Timbalan Perdana Menteri yang memimpin delegasi dalam JAK dan perundingan di London?', 'Tun Tan Siew Sin', 'Tunku Abdul Rahman Putra Al-Haj', 'Tun Abdul Razak bin Hussein', 'Tun Dr. Ismail', 'C', 'Beliau juga digelar Bapa Pembangunan.', 'Tun Abdul Razak, Timbalan Perdana Menteri, memimpin delegasi Persekutuan Tanah Melayu dalam JAK dan di London.'),
(131, 1, 'Apakah parti politik utama di Sarawak yang menentang Pembentukan Malaysia pada peringkat awal?', 'Parti Negara Sarawak (PANAS)', 'Sarawak United Peoples Party (SUPP)', 'Parti Pesaka Anak Sarawak (PESAKA)', 'Sarawak National Party (SNAP)', 'B', 'Parti ini ditubuhkan pada tahun 1959.', 'SUPP menentang cadangan Pembentukan Malaysia pada peringkat awal.'),
(132, 1, 'Mengapakah SUPP menolak cadangan Pembentukan Malaysia?', 'Mahu Sarawak merdeka serta-merta tanpa sebarang persekutuan', 'Mahu persekutuan Borneo sendiri atau merdeka berasingan dahulu', 'Mahu Sarawak bergabung dengan Brunei dan Singapura sahaja', 'Mahu Sarawak dikekalkan di bawah pentadbiran British', 'B', 'SUPP mahukan jalan yang berbeza untuk Sarawak.', 'SUPP mahu membentuk persekutuan sendiri bersama Brunei dan Borneo Utara, atau mencapai kemerdekaan berasingan terlebih dahulu.'),
(133, 1, 'Bagaimanakah Indonesia menentang penubuhan Malaysia secara luaran?', 'Menuntut Sarawak sebagai wilayah Indonesia di PBB pada 20 Januari 1963', 'Menyekat perdagangan dengan Malaysia pada 20 Januari 1962', 'Mengisytiharkan Konfrontasi dengan slogan Ganyang Malaysia pada 20 Januari 1963', 'Mengisytiharkan Konfrontasi dengan slogan Ganyang Malaysia pada 16 September 1963', 'C', 'Doktrin ini berbunyi seperti seruan untuk menghancurkan Malaysia.', 'Indonesia mengisytiharkan Konfrontasi dengan doktrin Ganyang Malaysia pada 20 Januari 1963.'),
(134, 1, 'Apakah bantahan luaran yang dikemukakan oleh Filipina terhadap Pembentukan Malaysia?', 'Mengisytiharkan Konfrontasi terhadap Malaysia', 'Menuntut Sabah sebagai sebahagian daripada wilayahnya', 'Menuntut Brunei dan Sabah sebagai wilayah bersama', 'Menuntut Sarawak sebagai sebahagian daripada wilayahnya', 'B', 'Tuntutan ini berkaitan sebuah wilayah di utara Borneo.', 'Filipina mendakwa Sabah sebahagian daripada hak wilayahnya.'),
(135, 1, 'Mengapakah Malaysia memilih pendekatan diplomasi melalui Pertubuhan Bangsa-Bangsa Bersatu (PBB) pada Ogos 1963?', 'Mengelakkan tandatangan Perjanjian Malaysia di London', 'Meredakan tentangan Indonesia dan Filipina melalui PBB', 'Meredakan tentangan SUPP melalui pengesahan Parlimen', 'Mendapatkan bantuan tentera PBB untuk menghadapi Indonesia', 'B', 'Pendekatan ini bertujuan membuktikan ketelusan kepada dunia.', 'Malaysia memilih diplomasi melalui PBB untuk meredakan tentangan Indonesia dan Filipina serta membuktikan hasrat sebenar rakyat Borneo.'),
(136, 1, 'Apakah nama misi khas PBB yang ditubuhkan pada 12 Ogos 1963 untuk meninjau semula pandangan di Sabah dan Sarawak?', 'Jawatankuasa Antara Kerajaan (JAK)', 'Jawatankuasa Setia Kawan Malaysia (JSKM)', 'Suruhanjaya Cobbold', 'United Nations Malaysia Mission (UNMM)', 'D', 'Namanya mengandungi singkatan PBB dalam bahasa Inggeris.', 'UNMM ditubuhkan pada 12 Ogos 1963 untuk meninjau semula pandangan rakyat Sabah dan Sarawak.'),
(137, 1, 'Siapakah tokoh PBB yang dilantik mengetuai misi UNMM semasa tinjauan di Borneo?', 'Sir Anthony Abell', 'Lord Lansdowne', 'U Thant', 'Laurence Michelmore', 'D', 'Beliau ialah pegawai kanan PBB, bukan wakil British.', 'Laurence Michelmore mengetuai misi UNMM di Sabah dan Sarawak.'),
(138, 1, 'Bilakah Laporan Rasmi United Nations Malaysia Mission (UNMM) dikeluarkan?', '16 September 1963', '12 Ogos 1963', '14 September 1963', '9 Julai 1963', 'C', 'Laporan dikeluarkan dua hari sebelum Pemasyhuran Malaysia.', 'Laporan UNMM dikeluarkan pada 14 September 1963, dua hari sebelum Pemasyhuran Malaysia.'),
(139, 1, 'Apakah penemuan muktamad Laporan UNMM mengenai pendirian rakyat Sabah dan Sarawak?', 'Majoriti rakyat Sabah menyokong tetapi Sarawak menolak', 'Majoriti rakyat menyokong tetapi tanpa pungutan suara bebas', 'Majoriti rakyat menolak dan mahu pungutan suara baharu', 'Majoriti rakyat menyokong Malaysia secara bebas dan demokratik', 'D', 'Laporan ini mengesahkan keputusan rakyat, bukan menolaknya.', 'UNMM mengesahkan bahawa majoriti rakyat Sabah dan Sarawak menyokong pembentukan Malaysia secara bebas dan demokratik.'),
(140, 1, 'Siapakah tokoh perunding diplomatik Malaysia yang aktif mengendalikan operasi penerangan dan keselamatan bagi menangkis cabaran Konfrontasi?', 'Tun Dr. Ismail Abdul Rahman', 'Tun Tan Siew Sin (MCA)', 'Tun V.T. Sambanthan (MIC)', 'Tun Muhammad Ghazali Shafie', 'D', 'Beliau juga pernah menjadi anggota Suruhanjaya Cobbold.', 'Tun Muhammad Ghazali Shafie giat dalam diplomasi, penerangan dan keselamatan menangkis cabaran Konfrontasi.'),
(141, 1, 'Siapakah tokoh pejuang Sabah yang memimpin pembacaan Pemasyhuran Malaysia di Kota Kinabalu pada 16 September 1963?', 'Donald Stephens (Tun Fuad Stephens)', 'Tun Temenggung Jugah anak Barieng', 'Stephen Kalong Ningkan', 'Tun Datu Mustapha bin Datu Harun', 'A', 'Beliau berasal dari Sabah dan pernah mengerusikan JSKM.', 'Donald Stephens memimpin pembacaan Pemasyhuran Malaysia di Kota Kinabalu.'),
(142, 1, 'Siapakah Pemimpin Utama Sarawak yang membacakan Teks Pemasyhuran Malaysia di Kuching pada 16 September 1963?', 'Datu Bandar Abang Haji Mustapha', 'Tun Datu Mustapha Datu Harun', 'Stephen Kalong Ningkan', 'Tun Temenggung Jugah anak Barieng', 'C', 'Beliau ialah Ketua Menteri Sarawak yang pertama.', 'Stephen Kalong Ningkan membacakan Teks Pemasyhuran Malaysia di Kuching.'),
(143, 1, 'Siapakah pemuka masyarakat Iban di Sarawak yang konsisten menyokong pembentukan Malaysia demi keselamatan wilayah?', 'Donald Stephens', 'Tun Datu Mustapha bin Datu Harun', 'Tun Temenggung Jugah anak Barieng', 'Lee Kuan Yew', 'C', 'Gelaran Temenggung diberikan kepada pemimpin adat.', 'Tun Temenggung Jugah ialah pemuka Iban yang konsisten menyokong pembentukan Malaysia.'),
(144, 1, 'Siapakah Yang di-Pertua Negeri Sabah yang pertama dilantik semasa pembentukan Malaysia pada tahun 1963?', 'Tun Temenggung Jugah anak Barieng', 'Tun Abang Haji Openg', 'Donald Stephens', 'Tun Datu Mustapha bin Datu Harun', 'D', 'Beliau juga pemimpin yang menubuhkan USNO.', 'Tun Datu Mustapha bin Datu Harun dilantik sebagai Yang di-Pertua Negeri Sabah yang pertama.'),
(145, 1, 'Bilakah tarikh rasmi Hari Pemasyhuran Malaysia yang diisytiharkan serentak?', '16 September 1963', '31 Ogos 1957', '27 Mei 1961', '31 Ogos 1963', 'A', 'Tarikh ini kini disambut sebagai Hari Malaysia.', 'Malaysia diisytiharkan serentak pada 16 September 1963.'),
(146, 1, 'Nyatakan empat lokasi utama majlis Pemasyhuran Malaysia yang diisytiharkan serentak pada 16 September 1963.', 'London, Kuala Lumpur, Kuching dan City Hall Singapura', 'Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall Singapura', 'Kuala Lumpur, Kuching, Pulau Pinang dan City Hall Singapura', 'Kuala Lumpur, Kuching, Kota Kinabalu dan Bandar Seri Begawan', 'B', 'Empat lokasi ini mewakili Tanah Melayu, Sarawak, Sabah dan Singapura.', 'Pemasyhuran dibuat serentak di Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall, Singapura.'),
(147, 1, 'Di manakah Tunku Abdul Rahman membaca Teks Pemasyhuran Malaysia di ibu negara?', 'Stadium Merdeka, Kuala Lumpur', 'Hotel Adelphi, Singapura', 'Istana Negara', 'Padang Kota Lama, Pulau Pinang', 'A', 'Stadium ini juga tempat Kemerdekaan Tanah Melayu dilaungkan pada 1957.', 'Tunku membaca Teks Pemasyhuran Malaysia di Stadium Merdeka, Kuala Lumpur.'),
(148, 1, 'Apakah lambang kedaulatan utama yang dikibarkan semasa perayaan Hari Pemasyhuran Malaysia pada 16 September 1963?', 'Bendera Pertubuhan Bangsa-Bangsa Bersatu', 'Bendera Persekutuan Tanah Melayu (11 jalur)', 'Bendera Union Jack British', 'Bendera Malaysia (Jalur Gemilang)', 'D', 'Bendera ini dikibarkan sebagai lambang negara baharu.', 'Bendera Malaysia (Jalur Gemilang) dikibarkan sebagai lambang kedaulatan negara baharu.'),
(149, 1, 'Susun peristiwa berikut mengikut kronologi yang betul: A. Laporan Suruhanjaya Cobbold; B. Cadangan Tunku di Singapura; C. Perjanjian Malaysia di London; D. Pemasyhuran Malaysia; E. Penubuhan JSKM.', 'E → B → A → C → D', 'B → E → A → C → D', 'B → A → E → C → D', 'B → E → C → A → D', 'B', 'Mulakan dengan pengumuman di Hotel Adelphi dan akhiri dengan Pemasyhuran.', 'B (27 Mei 1961), E (23 Julai 1961), A (21 Jun 1962), C (9 Julai 1963), D (16 September 1963).'),
(150, 1, 'Apakah iktibar dan ikatan utama yang dicapai oleh rakyat pelbagai kaum dan wilayah melalui pembentukan Malaysia?', 'Pergantungan sepenuhnya kepada kuasa asing', 'Toleransi, kerjasama diplomasi dan perpaduan berbilang kaum', 'Persaingan antara wilayah untuk menguasai pentadbiran', 'Pengasingan kaum demi mengekalkan kestabilan', 'B', 'Fikirkan nilai yang menyatukan rakyat berbilang kaum.', 'Pembentukan Malaysia berjaya melalui toleransi, kerjasama diplomasi, perpaduan berbilang kaum dan muafakat kepimpinan.');
