-- ====================================================================
-- SejarahWira  |  ERA 1: Pembentukan Malaysia 1963  |  seed_era1.sql
-- 3 naratif (6 + 6 + 6 babak = 18 babak), setiap babak ada 1 quest, serta 50 soalan.
-- SETIAP naratif merangkumi keenam-enam topik utama dengan fakta yang sama (cadangan Malaysia, JSKM dan Cobbold,
-- JAK, ancaman, Perjanjian London dan PBB, Pemasyhuran). Naratif hanya berbeza pada tokoh, sudut pandang dan cabaran.
--
-- Pelajar MERASUK jasad tokoh sebenar (peranan naratif):
--   Naratif 1 = Tunku Abdul Rahman (NPC 1), Naratif 2 = Donald Stephens (NPC 3),
--   Naratif 3 = Tun Ghazali Shafie (NPC 10).
-- Baris dialog tanpa penutur (npcID NULL) ialah baris "Pemain" / "kau" yang dituturkan tokoh peranan.
-- Baris naratif tanpa babak (sceneID NULL): 1 = tugas bersejarah, 2 = pembuka pengajaran,
--   3 = pengenalan peranan oleh Pendekar Bayang.
-- Setiap quest ada "aftermath" (Akibat jika salah), pilihan salah jenis 3/5 ada "consequence",
-- dan satu "Giliran Anda" (turns). Data sahaja (tiada jadual atau lajur baharu).
-- Lencana, artifak dan kemajuan era TIDAK disentuh.
--
-- Jalankan SELEPAS seed.sql:
--   mysql --default-character-set=utf8mb4 -u root -p <nama_db> < database/seed_era1.sql
-- Selamat dijalankan berulang kali (kandungan Era 1 lama dipadam dahulu). Era lain tidak disentuh.
-- ====================================================================
SET NAMES utf8mb4;
START TRANSACTION;

-- 1. Buang kandungan Era 1 lama (babak, dialog, quest, sokongan dipadam sekali: ON DELETE CASCADE).
DELETE FROM Narrative WHERE eraID = 1;

-- 2. NPC: nama fail gambar mengikut folder npc sebenar.
ON DUPLICATE KEY UPDATE name = VALUES(name), biography = VALUES(biography), contribution = VALUES(contribution), asset = VALUES(asset);

-- 3. Naratif

-- 4. Babak (sceneStoryline = kad garis masa dalam suara "kau"; asset = latar belakang)

-- 5. Quest (1 Susun Garis Masa, 2 Cari Bukti, 3 Bantu Tokoh, 4 Padanan, 5 Nyahkod Clue)
--    instruction = taklimat misi, description = objektif pembelajaran

-- 6. Sokongan: baris babak = petunjuk babak; baris quest = bisikan (hint), catatan diari (explanation), pujian (feedback)

-- 7. Dialog: baris peranan (tanpa babak) dan dialog babak

-- 8. Bank soalan Era 1 (50 soalan aneka pilihan, ID 101-150)
ON DUPLICATE KEY UPDATE eraID = VALUES(eraID);

DELETE FROM Question WHERE bankID = 1;


COMMIT;